window.BOOK={"key":"maraqi","app":"mutoon-maraqi","lsk":"mutoon_maraqi_v1","prefix":"ma_","title":"مراقي السعود","sub":"مراقي السعود لمبتغي الرقي والصعود في أصول الفقه المالكي · عبد الله بن الحاج إبراهيم العلوي الشنقيطي (ت ١٢٣٣هـ) · ١٠٠١ بيتًا","poems":[{"id":"maraqi","title":"مراقي السعود","nazim":"سيدي عبد الله بن الحاج إبراهيم العلوي الشنقيطي","death":"ت ١٢٣٣هـ","meter":"الرجز","source":"كتاب أونلاين (عن الشاملة الذهبية): متن مراقي السعود لمبتغي الرقي والصعود، مقابلًا بنثر الورود (تحقيق علي العمران) ونشر البنود للناظم على المكتبة الشاملة","srcUrl":"https://ketabonline.com/ar/books/25829","note":"لا توجد نسخة رقمية مشكولة كاملة للمتن، فأُخذ ترتيب الأبيات من نسخة المتن المفردة، وقوبل لفظه بسكربت كلمةً كلمةً بأبيات «نثر الورود» للشنقيطي (تحقيق علي العمران) و«نشر البنود» شرح الناظم نفسه، وأُثبت ما اتفقا عليه حيث خالفهما المتن. الشكل من نثر الورود ثم من نسخة المتن، وهو جزئي (نحو ٣٠٪ من الحروف)، وعدد الأبيات ١٠٠١ وهو العدد المشهور «ألفٌ وبيتٌ عددُ المراقي». والشكل المنشور جزئي (نحو ٣٠٪ من نثر الورود)، فأكمل الذكاء الاصطناعي باقي الحركات على الإعراب والوزن، فإذا شككت بحركة فراجع شيخك.","verses":[["يَقُولُ عَبْدُ اللَّهِ وَهْوَ ارْتَسَمَا","سِمًى لَهُ وَالْعَلَوِيُّ الْمُنْتَمَى"],["الْحَمْدُ لِلَّهِ عَلَى مَا فَاضَا","مِنَ الْجَدَى الَّذِي دُهُورًا غَاضَا"],["وَجَعَلَ الْفُرُوعَ وَالْأُصُولَا","لِمَنْ يَرُومُ نَيْلَهَا مَحْصُولَا"],["وَشَادَ ذَا الدِّينِ بِمَنْ سَادَ الْوَرَى","فَهْوَ الْمُجَلِّي وَالْوَرَى إِلَى وَرَا"],["مُحَمَّدٍ مُنَوِّرِ الْقُلُوبِ","وَكَاشِفِ الْكَرْبِ لَدَى الْكُرُوبِ"],["صَلَّى عَلَيْهِ رَبُّنَا وَسَلَّمَا","وَآلِهِ وَمَنْ لِشَرْعِهِ انْتَمَى"],["هَذَا وَحِينَ قَدْ رَأَيْتُ الْمَذْهَبَا","رُجْحَانَهُ لَهُ الْكَثِيرُ ذَهَبَا"],["وَمَا سِوَاهُ مِثْلَ عَنْقَا مُغْرِبِ","فِي كُلِّ قُطْرٍ مِنْ نَوَاحِي الْمَغْرِبِ"],["أَرَدْتُ أَنْ أَجْمَعَ مِنْ أُصُولِهِ","مَا فِيهِ بُغْيَةٌ لِذِي فُصُولِهِ"],["مُنْتَبِذًا عَنْ مَقْصِدِي مَا ذُكِرَا","لَدَى الْفُنُونِ غَيْرِهِ مُحَرِّرَا"],["سَمَّيْتُهُ مَرَاقِيَ السُّعُودِ","لِمُبْتَغِي الرُّقِيِّ وَالصُّعُودِ"],["أَسْتَوْهِبُ اللَّهَ الْكَرِيمَ الْمَدَدَا","وَنَفْعَهُ لِلْقَارِئِينَ أَبَدَا"],["أَوَّلُ مَنْ أَلَّفَهُ فِي الْكُتُبِ","مُحَمَّدُ بْنُ شَافِعِ الْمُطَّلِبِي"],["وَغَيْرُهُ كَانَ لَهُ سَلِيقَهْ","مِثْلُ الَّذِي لِلْعُرْبِ مِنْ خَلِيقَهْ"],["الَاحْكَامُ وَالْأَدِلَّةُ الْمَوْضُوعُ","وَكَوْنُهُ هَذِي فَقَطْ مَسْمُوعُ"],["أُصُولُهُ دَلَائِلُ الْإِجْمَالِ","وَطُرُقُ التَّرْجِيحِ قَيْدٌ تَالِي"],["وَمَا لِلِاجْتِهَادِ مِنْ شَرْطٍ وَضَحْ","وَيُطْلَقُ الْأَصْلُ عَلَى مَا قَدْ رَجَحْ"],["وَالْفَرْعُ حُكْمُ الشَّرْعِ قَدْ تَعَلَّقَا","بِصِفَةِ الْفِعْلِ كَنَدْبٍ مُطْلَقَا"],["وَالْفِقْهُ هُوْ الْعِلْمُ بِالْأَحْكَامِ","لِلشَّرْعِ وَالْفِعْلِ نَمَاهَا النَّامِي"],["أَدِلَّةُ التَّفْصِيلِ مِنْهَا مُكْتَسَبْ","وَالْعِلْمُ بِالصَّلَاحِ فِيمَا قَدْ ذَهَبْ"],["فَالْكُلُّ مِنْ أَهْلِ الْمَنَاحِي الْأَرْبَعَهْ","يَقُولُ لَا أَدْرِي فَكُنْ مُتَّبِعَهْ"],["كَلَامُ رَبِّي إِنْ تَعَلَّقَ بِمَا","يَصِحُّ فِعْلًا لِلْمُكَلَّفِ اعْلَمَا"],["مِنْ حَيْثُ إِنَّهُ بِهِ مُكَلَّفُ","فَذَاكَ بِالْحُكْمِ لَدَيْهِمْ يُعْرَفُ"],["قَدْ كُلِّفَ الصَّبِي عَلَى الَّذِي اعْتُمِي","بِغَيْرِ مَا وَجَبَ وَالْمُحَرَّمِ"],["وَهْوَ إِلْزَامُ الَّذِي يَشُقُّ","أَوْ طَلَبٌ فَاهَ بِكُلٍّ خَلْقُ"],["لَكِنَّهُ لَيْسَ يُفِيدُ فَرْعَا","فَلَا تَضِقْ لِفَقْدِ فَرْعٍ ذَرْعَا"],["وَالْحُكْمُ مَا بِهِ يَجِيءُ الشَّرْعُ","وَأَصْلُ كُلِّ مَا يَضُرُّ الْمَنْعُ"],["ذُو فَتْرَةٍ بِالْفَرْعِ لَا يُرَاعُ","وَفِي الْأُصُولِ بَيْنَهُمْ نِزَاعُ"],["ثُمَّ الْخِطَابُ الْمُقْتَضِي لِلْفِعْلِ","جَزْمًا فَإِيجَابٌ لَدَى ذِي النَّقْلِ"],["وَغَيْرُهُ النَّدْبُ وَمَا التَّرْكَ طَلَبْ","جَزْمًا فَتَحْرِيمٌ لَهُ الْإِثْمُ انْتَسَبْ"],["أَوْلَا مَعَ الْخُصُوصِ أَوْلَا فَعِ ذَا","خِلَافَ الَاوْلَى وَكَرَاهَةً خُذَا"],["لِذَاكَ وَالْإِبَاحَةُ الْخِطَابُ","فِيهِ اسْتَوَى الْفِعْلُ وَالِاجْتِنَابُ"],["وَمَا مِنَ الْبَرَاءَةِ الْأَصْلِيَّهْ","قَدْ أُخِذَتْ فَلَيْسَتِ الشَّرْعِيَّهْ"],["وَهِيَ وَالْجَوَازُ قَدْ تَرَادَفَا","فِي مُطْلَقِ الْإِذْنِ لَدَى مَنْ سَلَفَا"],["وَالْعِلْمُ وَالْوُسْعُ عَلَى الْمَعْرُوفِ","شَرْطٌ يَعُمُّ كُلَّ ذِي تَكْلِيفِ"],["ثُمَّ خِطَابُ الْوَضْعِ هُوْ الْوَارِدُ","بِأَنَّ هَذَا مَانِعٌ أَوْ فَاسِدُ"],["أَوْ ضِدُّهُ أَوْ أَنَّهُ قَدْ أَوْجَبَا","شَرْطًا يَكُونُ اوْ يَكُونُ سَبَبَا"],["وَهُوَ مِنْ ذَاكَ أَعَمُّ مُطْلَقًا","وَالْفَرْضُ وَالْوَاجِبُ قَدْ تَوَافَقَا"],["كَالْحَتْمِ وَاللَّازِمِ مَكْتُوبٍ وَمَا","فِيهِ اشْتِبَاهٌ لِلْكَرَاهَةِ انْتَمَى"],["وَلَيْسَ فِي الْوَاجِبِ مِنْ نَوَالِ","عِنْدَ انْتِفَاءِ قَصْدِ الِامْتِثَالِ"],["فِيمَا لَهُ النِّيَّةُ لَا تُشْتَرَطُ","وَغَيْرُ مَا ذَكَرْتُهُ فَغَلَطُ"],["وَمِثْلُهُ التَّرْكُ لِمَا يُحَرَّمُ","مِنْ غَيْرِ قَصْدِ ذَا نَعَمْ مُسَلَّمُ"],["فَضِيلَةٌ وَالنَّدْبُ وَالَّذِي اسْتُحِبّْ","تَرَادَفَتْ ثُمَّ التَّطَوُّعُ انْتُخِبْ"],["رَغِيبَةٌ مَا فِيهِ رَغَّبَ النَّبِي","بِذِكْرِ مَا فِيهِ مِنَ الْأَجْرِ جُبِي"],["أَوْ دَامَ فِعْلُهُ بِوَصْفِ النَّفْلِ","وَالنَّفْلَ مِنْ تِلْكَ الْقُيُودِ أَخْلِ"],["وَالْأَمْرِ بَلْ أَعْلَمَ بِالثَّوَابِ","فِيهِ نَبِيُّ الرُّشْدِ وَالصَّوَابِ"],["وَسُنَّةٌ مَا أَحْمَدُ قَدْ وَاظَبَا","عَلَيْهِ وَالظُّهُورُ فِيهِ وَجَبَا"],["وَبَعْضُهُمْ سَمَّى الَّذِي قَدْ أُكِّدَا","مِنْهَا بِوَاجِبٍ فَخُذْ مَا قُيِّدَا"],["وَالنَّفْلُ لَيْسَ بِالشُّرُوعِ يَجِبُ","فِي غَيْرِ مَا نَظَمَهُ مُقَرَّبُ"],["قِفْ وَاسْتَمِعْ مَسَائِلًا قَدْ حَكَمُوا","بِأَنَّهَا بِالِابْتِدَاءِ تَلْزَمُ"],["صَلَاتُنَا وَصَوْمُنَا وَحَجُّنَا","وَعُمْرَةٌ لَنَا كَذَا اعْتِكَافُنَا"],["طَوَافُنَا مَعَ ائْتِمَامِ الْمُقْتَدِي","فَيَلْزَمُ الْقَضَا بِقَطْعِ عَامِدِ"],["مَا مِنْ وُجُودِهِ يَجِيءُ الْعَدَمُ","وَلَا لُزُومَ فِي انْعِدَامٍ يُعْلَمُ"],["بِمَانِعٍ يَمْنَعُ لِلدَّوَامِ","وَالِإبْتِدَا أَوْ آخِرِ الْأَقْسَامِ"],["أَوْ أَوَّلٍ فَقَطْ عَلَى نِزَاعِ","كَالطَّوْلِ الِاسْتِبْرَاءِ وَالرَّضَاعِ"],["وَلَازِمٌ مِنِ انْتِفَاءِ الشَّرْطِ","عَدَمُ مَشْرُوطٍ لَدَى ذِي الضَّبْطِ"],["كَسَبَبٍ وَذَا الْوُجُودُ لَازِمُ","مِنْهُ وَمَا فِي ذَاكَ شَيْءٌ قَائِمُ"],["وَاجْتَمَعَ الْجَمِيعُ فِي النِّكَاحِ","وَمَا هُوَ الْجَالِبُ لِلنَّجَاحِ"],["وَالرُّكْنُ جُزْءُ الذَّاتِ وَالشَّرْطُ خَرَجْ","وَصِيغَةٌ دَلِيلُهَا فِي الْمُنْتَهَجْ"],["وَمَعْ عِلَّةٍ تَرَادُفُ السَّبَبْ","وَالْفَرْقُ بَعْضُهُمْ إِلَيْهِ قَدْ ذَهَبْ"],["شَرْطُ الْوُجُوبِ مَا بِهِ نُكَلَّفُ","وَعَدَمُ الطَّلَبِ فِيهِ يُعْرَفُ"],["مِثْلُ دُخُولِ الْوَقْتِ وَالنَّقَاءِ","وَكَبُلُوغِ بَعْثِ الَانْبِيَاءِ"],["وَمَعْ تَمَكُّنٍ مِنَ الْفِعْلِ الْأَدَا","وَعَدَمُ الْغَفْلَةِ وَالنَّوْمِ بَدَا"],["وَشَرْطُ صِحَّةٍ بِهِ اعْتِدَادُ","بِالْفِعْلِ مِنْهُ الطُّهْرُ يُسْتَفَادُ"],["وَالشَّرْطُ فِي الْوُجُوبِ شَرْطٌ فِي الْأَدَا","وَعَزْوُهُ لِلِاتِّفَاقِ وُجِدَا"],["وَصِحَّةٌ وِفَاقُ ذِي الْوَجْهَيْنِ","لِلشَّرْعِ مُطْلَقًا بِدُونِ مَيْنِ"],["وَفِي الْعِبَادَةِ لَدَى الْجُمْهُورِ","أَنْ يُسْقِطَ الْقَضَا مَدَى الدُّهُورِ"],["يُبْنَى عَلَى الْقَضَاءِ بِالْجَدِيدِ","أَوْ أَوَّلِ الْأَمْرِ لَدَى الْمُجِيدِ"],["وَهْيَ وِفَاقُهُ لِنَفْسِ الْأَمْرِ","أَوْ ظَنَّ مَأْمُورٍ لَدَى ذِي خُبْرِ"],["بِصِحَّةِ الْعَقْدِ يَكُونُ الَاثَرُ","وَفِي الْفَسَادِ عَكْسُ هَذَا يَظْهَرُ"],["إِنْ لَمْ تَكُنْ حَوَالَةٌ أَوْ تَلَفُ","تَعَلُّقُ الْحَقِّ وَنَقْصٌ يُؤْلَفُ"],["كِفَايَةُ الْعِبَادَةِ الْإِجْزَاءُ","وَهْيَ انْ يَسْقُطَ الِاقْتِضَاءُ"],["أَوِ السُّقُوطُ لِلْقَضَا وَذَا أَخَصّْ","مِنْ صِحَّةٍ إِذْ بِالْعِبَادَةِ يُخَصّْ"],["وَالصِّحَّةُ الْقَبُولُ فِيهَا يَدْخُلُ","وَبَعْضُهُمْ لِلِاسْتِوَاءِ يَنْقُلُ"],["وَخُصِّصَ الْإِجْزَاءُ بِالْمَطْلُوبِ","وَقِيلَ بَلْ يَخْتَصُّ بِالْمَكْتُوبِ"],["وَقَابِلِ الصِّحَّةَ بِالْبُطْلَانِ","وَهْوَ الْفَسَادُ عِنْدَ أَهْلِ الشَّانِ"],["وَخَالَفَ النُّعْمَانُ فَالْفَسَادُ","مَا نَهْيُهُ لِلْوَصْفِ يُسْتَفَادُ"],["فِعْلُ الْعِبَادَةِ بِوَقْتٍ عُيِّنَا","شَرْعًا لَهَا بِاسْمِ الْأَدَاءِ قُرِنَا"],["وَكَوْنُهُ بِفِعْلِ بَعْضٍ يَحْصُلُ","لِعَاضِدِ النَّصِّ هُوَ الْمُعَوَّلُ"],["وَقِيلَ مَا فِي وَقْتِهِ أَدَاءُ","وَمَا يَكُونُ خَارِجًا قَضَاءُ"],["وَالْوَقْتُ مَا قَدَّرَهُ مَنْ شَرَعَا","مِنْ زَمَنٍ مُضَيِّقًا مُوَسَّعَا"],["وَضِدُّهُ الْقَضَا تَدَارُكًا لِمَا","سَبْقُ الَّذِي أَوْجَبَهُ قَدْ عُلِمَا"],["مِنَ الْأَدَاءِ وَاجِبٌ وَمَا مُنِعْ","وَمِنْهُ مَا فِيهِ الْجَوَازُ قَدْ سُمِعْ"],["وَاجْتَمَعَ الْأَدَاءُ وَالْقَضَاءُ","وَرُبَّمَا يَنْفَرِدُ الْأَدَاءُ"],["وَانْتَفَيَا فِي النَّفْلِ وَالْعِبَادَهْ","تَكْرِيرُهَا لَوْ خَارِجًا إِعَادَهْ"],["لِلْعُذْرِ وَالرُّخْصَةُ حُكْمٌ غُيِّرَا","إِلَى سُهُولَةٍ لِعُذْرٍ قُرِّرَا"],["مَعْ قِيَامِ عِلَّةِ الْأَصْلِيِّ","وَغَيْرُهَا عَزِيمَةُ النَّبِيِّ"],["وَتِلْكَ فِي الْمَأْذُونِ جَزْمًا تُوجَدُ","وَغَيْرُهُ فِيهِ لَهُمْ تَرَدُّدُ"],["وَرُبَّمَا تَجِي لِمَا أُخْرِجَ مِنْ","أَصْلٍ بِمُطْلَقِ امْتِنَاعِهِ قَمِنْ"],["وَمَا بِهِ لِلْخَبَرِ الْوُصُولُ","بِنَظَرٍ صَحَّ هُوَ الدَّلِيلُ"],["وَالنَّظَرُ الْمُوصِلُ مِنْ فِكْرٍ إِلَى","ظَنٍّ بِحُكْمٍ أَوْ لِعِلْمٍ مُسْجَلَا"],["الَادْرَاكُ مِنْ غَيْرِ قَضًا تَصَوُّرُ","وَمَعْهُ تَصْدِيقٌ وَذَا مُشْتَهِرُ"],["جَازِمُهُ دُونَ تَغَيُّرٍ عُلِمْ","عِلْمًا وَغَيْرُهُ اعْتِقَادٌ يَنْقَسِمْ"],["إِلَى صَحِيحٍ إِنْ يَكُنْ يُطَابِقُ","أَوْ فَاسِدٍ إِنْ هُوَ لَا يُوَافِقُ"],["وَالْوَهْمُ وَالظَّنُّ وَشَكٌّ مَا احْتَمَلْ","لِرَاجِحٍ أَوْ ضِدِّهِ أَوْ مَا اعْتَدَلْ"],["وَالْعِلْمُ عِنْدَ الْأَكْثَرِينَ يَخْتَلِفْ","جَزْمًا وَبَعْضُهُمْ بِنَفْيِهِ عُرِفْ"],["وَإِنَّمَا لَهُ لَدَى الْمُحَقِّقِ","تَفَاوُتٌ بِحَسَبِ التَّعَلُّقِ"],["لِمَا لَهُ مِنِ اتِّحَادٍ مُنْحَتِمْ","مَعَ تَعَدُّدٍ لِمَعْلُومٍ عُلِمْ"],["يُبْنَى عَلَيْهِ الزَّيْدُ وَالنُّقْصَانُ","هَلْ يَنْتَمِي إِلَيْهِمَا الْإِيمَانُ"],["وَالْجَهْلُ جَا فِي الْمَذْهَبِ الْمَحْمُودِ","هُوَ انْتِفَاءُ الْعِلْمِ بِالْمَقْصُودِ"],["زَوَالُ مَا عُلِمَ قُلْ نِسْيَانُ","وَالْعِلْمُ فِي السَّهْوِ لَهُ اكْتِنَانُ"],["مَا رَبُّنَا لَمْ يَنْهَ عَنْهُ حَسَنُ","وَغَيْرُهُ الْقَبِيحُ وَالْمُسْتَهْجَنُ"],["هَلْ يَجِبُ الصَّوْمُ عَلَى ذِي الْعُذْرِ","كَحَائِضٍ وَمُمْرَضٍ وَسَفْرِ"],["وُجُوبُهُ فِي غَيْرِ الَاوَّلِ رَجَحْ","وَضَعْفُهُ فِيهِ لَدَيْهِمُ وَضَحْ"],["وَهْوَ فِي وُجُوبِ قَصْدٍ لِلْأَدَا","أَوْ ضِدِّهِ لِقَائِلٍ بِهِ بَدَا"],["وَلَا يُكَلِّفُ بِغَيْرِ الْفِعْلِ","بَاعِثُ الَانْبِيَا وَرَبُّ الْفَضْلِ"],["فَكَفُّنَا بِالنَّهْيِ مَطْلُوبُ النَّبِي","وَالتَّرْكُ فِعْلٌ فِي صَحِيحِ الْمَذْهَبِ"],["لَهُ فُرُوعٌ ذُكِرَتْ فِي الْمَنْهَجِ","وَسَرْدُهَا مِنْ بَعْدِ ذَا الْبَيْتِ يَجِي"],["مِنْ شُرْبٍ أَوْ خَيْطٍ ذَكَاةٍ فَضْلِ مَا","وَعَمَدٍ رَسْمٍ شَهَادَةٍ وَمَا"],["عَطَّلَ نَاظِرٌ وَذُو الرَّهْنِ كَذَا","مُفَرِّطٌ فِي الْعَلْفِ فَادْرِ الْمَأْخَذَا"],["وَكَالَّتِي رُدَّتْ بِعَيْبٍ وَعَدِمْ","وَلِيُّهَا وَشِبْهِهَا مِمَّا عُلِمْ"],["وَالْأَمْرُ قَبْلَ الْوَقْتِ قَدْ تَعَلَّقَا","بِالْفِعْلِ لِلْإِعْلَامِ قَدْ تَحَقَّقَا"],["وَبَعْدِ لِلْإِلْزَامِ يَسْتَمِرُّ","حَالَ التَّلَبُّسِ وَقَوْمٌ فَرُّوا"],["فَلَيْسَ يُجْزِي مَنْ لَهُ يُقَدِّمُ","وَلَا عَلَيْهِ دُونَ حَظْرٍ يُقْدِمُ"],["وَذَا التَّعَبُّدُ وَمَا تَمَحَّضَا","لِلْفِعْلِ فَالتَّقْدِيمُ فِيهِ مُرْتَضَى"],["وَمَا إِلَى هَذَا وَهَذَا يَنْتَسِبْ","فَفِيهِ خُلْفٌ دُونَ نَصٍّ قَدْ جُلِبْ"],["وَقَالَ إِنَّ الْأَمْرَ لَا يُوَجَّهُ","إِلَّا لَدَى تَلَبُّسٍ مُنْتَبِهُ"],["فَاللَّوْمُ قَبْلَهُ عَلَى التَّلَبُّسِ","بِالْكَفِّ وَهْيَ مِنْ أَدَقِّ الْأُسُسِ"],["وَهِيَ فِي فَرْضِ الْكِفَايَةِ فَهَلْ","يَسْقُطُ الِاثْمُ بِشُرُوعٍ قَدْ حَصَلْ"],["لِلِامْتِثَالِ كَلَّفَ الرَّقِيبُ","فَمُوجِبٌ تَمَكُّنًا مُصِيبُ"],["أَوْ بَيْنَهُ وَالِابْتِلَا تَرَدَّدَا","شَرْطُ تَمَكُّنٍ عَلَيْهِ انْفَقَدَا"],["عَلَيْهِ تَكْلِيفٌ يَجُوزُ وَيَقَعْ","مَعَ عِلْمِ مَنْ أُمِرَ بِالَّذِي امْتَنَعْ"],["فِي عِلْمِ مَنْ أَمَرَ كَالْمَأْمُورِ","فِي الْمَذْهَبِ الْمُحَقَّقِ الْمَنْصُورِ"],["لَفْظٌ مُنَزَّلٌ عَلَى مُحَمَّدِ","لِأَجْلِ الِاعْجَازِ وَلِلتَّعَبُّدِ"],["وَلَيْسَ لِلْقُرْآنِ تُعْزَى الْبَسْمَلَهْ","وَكَوْنُهَا مِنْهُ الْخِلَافِي نَقَلَهْ"],["وَبَعْضُهُمْ إِلَى الْقِرَاءَةِ نَظَرْ","وَذَاكَ لِلْوِفَاقِ رَأْيٌ مُعْتَبَرْ"],["وَلَيْسَ مِنْهُ مَا بِالْآحَادِ رُوِي","فَلِلْقِرَاءَةِ بِهِ نَفْيٌ قَوِي"],["كَالِاحْتِجَاجِ غَيْرَ مَا تَحَصَّلَا","فِيهِ ثَلَاثَةٌ فَجَوِّزْ مُسْجَلَا"],["صِحَّةُ الِاسْنَادِ وَوَجْهٌ عَرَبِي","وَوَفْقُ خَطِّ الْأُمِّ شَرْطٌ مَا أُبِي"],["مِثْلُ الثَّلَاثَةِ وَرَجِّحِ النَّظَرْ","تَوَاتُرًا لَهَا لَدَى مَنْ قَدْ غَبَرْ"],["تَوَاتُرُ السَّبْعِ عَلَيْهِ أَجْمَعُوا","وَلَمْ يَكُنْ فِي الْوَحْيِ حَشْوٌ يَقَعُ"],["وَمَا بِهِ يُعْنَى بِلَا دَلِيلِ","غَيْرُ الَّذِي ظَهَرَ لِلْعُقُولِ"],["وَالنَّقْلُ بِالْمُنْضَمِّ قَدْ يُفِيدُ","لِلْقَطْعِ وَالْعَكْسُ لَهُ بَعِيدٌ"],["مَعْنًى لَهُ فِيْ الْقَصْدِ قُلْ تَأَصُّلُ","وَهُوَ الَّذِيْ اللَّفْظُ به يُسْتَعْمَلُ"],["نصٌّ إذَا أَفَادَ مَا لَا يَحْتَمِلْ","غَيْرًا وَظَاهِرٌ إِنِ الْغَيْرُ احْتُمِلْ"],["وَالْكُلُّ مِنْ ذَيْنِ لَهُ تَجَلَّى","وَيُطْلَقُ النَّصُّ عَلى مَا دَلّا"],["وَفِيْ كَلامِ الْوَحْيِ وَالْمَنْطُوْقُ هَلْ","مَا لَيْسَ بِالصَّرِيْحِ فِيْهِ قَدْ دَخَلْ"],["وَهْوَ دَلَالَةُ اقْتَضَاءٍ أَنْ يَدُلْ","لَفْظٌ عَلى مَا دُوْنَهُ لَا يَسْتَقِلْ"],["دَلَالَةَ اللُّزُوْمِ مِثْلُ ذَاتِ","إِشَارَةٍ كَذَاكَ الْايْمَا آتِ"],["فَأَوَّلٌ إِشَارَةُ اللَّفْظِ لِمَا","لَمْ يَكُنِ الْقَصْدُ لَهُ قَدْ عُلِمَا"],["دَلَالَةُ الْإِيْمَاءِ وَالتَّنْبِيْهِ","فِي الْفَنِّ تُقْصَدُ لَدَى ذَوَيْهِ"],["أَنْ يُقْرَنَ الْوَصْفُ بِحُكْمٍ إِن يَّكُنْ","لِغَيْرِ عِلَّةٍ يَعِبْهُ مَنْ فَطِنْ"],["وَغَيْرُ مَنْطُوْقٍ هُوَ الْمَفْهُوْمُ","مِنْهُ الْمُوَافَقَةُ قُلْ مَعْلُوْمٌ"],["يُسْمَى بِتَنْبِيْهِ الْخِطَابِ وَوَرَدْ","فَحْوَى الْخِطَابِ اسْمًا لَهُ فِيْ الْمُعْتَمَدْ"],["إِعْطَاءُ مَا لِلَّفْظَةِ الْمَسْكُوْتَا","مِنْ بَابٍ أَوْلى نَفْيًا أَوْ ثُبُوْتَا"],["وَقِيْلَ ذَا فَحْوَى الْخِطَابِ وَالَّذِيْ","سَاوَى بِلَحْنِهِ دَعَاهُ الْمُحْتَذِيْ"],["دَلَالَةُ الْوِفَاقِ لِلْقِيَاسِ","وَهْوَ الْجَلِي تُعْزى لَدَى أُنَاسِ"],["وَقِيلَ لِلَّفْظِ مَعَ الْمَجَازِ","وَعَزْوُهَا لِلنَّقْلِ ذُو جَوَازِ"],["وَغَيْرُ مَا مَرَّ هُوَ الْمُخَالَفَهْ","ثُمَّتَ تَنْبِيهُ الْخِطَابِ خَالَفَهْ"],["كَذَا دَلِيلٌ لِلْخِطَابِ انْضَافَا","وَدَعْ إِذَا السَّاكِتُ عَنْهُ خَافَا"],["أَوْ جَهِلَ الْحُكْمَ أَوِ النُّطْقُ انْجَلَبْ","لِلسُّؤْلِ أَوْ جَرْيٍ عَلَى الَّذِي غَلَبْ"],["أَوِ امْتِنَانٍ أَوْ وِفَاقِ الْوَاقِعِ","وَالْجَهْلِ وَالتَّأْكِيدِ عِنْدَ السَّامِعِ"],["وَمُقْتَضَى التَّخْصِيصِ لَيْسَ يَحْظُلُ","قَيْسًا وَمَا عُرِضَ لَيْسَ يَشْمُلُ"],["وَهْوَ ظَرْفٌ عِلَّةٌ وَعَدَدُ","وَمِنْهُ شَرْطٌ غَايَةٌ تُعْتَمَدُ"],["وَالْحَصْرُ وَالصِّفَةُ مِثْلُ مَا عُلِمْ","مِنْ غَنَمٍ سَامَتْ وَسَائِمِ الْغَنَمْ"],["مَعْلُوفَةُ الْغَنَمِ أَوْ مَا يُعْلَفُ","الْخُلْفُ فِي النَّفْيِ لِأَيٍّ يُصْرَفُ"],["أَضْعَفُهَا اللَّقَبُ وَهْوَ مَا أُبِي","مِنْ دُونِهِ نَظْمُ الْكَلَامِ الْعَرَبِي"],["أَعْلَاهُ لَا يُرْشِدُ إِلَّا الْعُلَمَا","فَمَا لِمَنْطُوقٍ بِضَعْفٍ انْتَمَى"],["فَالشَّرْطُ فَالْوَصْفُ الَّذِي يُنَاسِبُ","فَمُطْلَقُ الْوَصْفِ الَّذِي يُقَارِبُ"],["فَعَدَدٌ ثَمَّتَ تَقْدِيمٌ يَلِي","وَهُوَ حُجَّةٌ عَلَى النَّهْجِ الْجَلِي"],["مِنْ لُطْفِ رَبِّنَا بِنَا تَعَالَى","تَوْسِيعُهُ فِي نُطْقِنَا الْمَجَالَا"],["وَمَا مِنَ الْأَلْفَاظِ لِلْمَعْنَى وُضِعْ","قُلْ لُغَةٌ بِالنَّقْلِ يَدْرِي مَنْ سَمِعْ"],["مَدْلُولُهَا الْمَعْنَى وَلَفْظٌ مُفْرَدُ","مُسْتَعْمَلًا وَمُهْمَلًا قَدْ يُوجَدُ"],["وَذُو تَرَكُّبٍ وَوَضْعُ النَّكِرَهْ","لِمُطْلَقِ الْمَعْنَى فَرِيقٌ نَصَرَهْ"],["وَهِيَ لِلذِّهْنِ لَدَى ابْنِ الْحَاجِبِ","وَكَمْ إِمَامٍ لِلْخِلَافِ ذَاهِبِ"],["وَلَيْسَ لِلْمَعْنَى بِلَا احْتِيَاجِ","لَفْظٌ كَمَا لِشَارِحِ الْمِنْهَاجِ"],["وَاللُّغَةُ الرَّبُّ لَهَا قَدْ وَضَعَا","وَعَزْوُهَا لِلِاصْطِلَاحِ سُمِعَا"],["فَبِالْإِشَارَةِ وَبِالتَّعَيُّنِ","كَالطِّفْلِ فَهْمُ ذِي الْخَفَا وَالْبَيِّنِ"],["يُبْنَى عَلَيْهِ الْقَلْبُ وَالطَّلَاقُ","بِكَاسْقِنِي الشَّرَابَ وَالْعَتَاقُ"],["هَلْ تَثْبُتُ اللُّغَةُ بِالْقِيَاسِ","وَالثَّالِثُ الْفَرْقُ لَدَى أُنَاسِ"],["مَحَلُّهُ عِنْدَهُمُ الْمُشْتَقُّ","وَمَا عَدَاهُ جَاءَ فِيهِ الْوَفْقُ"],["وَفَرْعُهُ الْمَبْنِيُّ خِفَّةُ الْكُلَفْ","فِيمَا بِجَامِعٍ يَقِيسُهُ السَّلَفْ"],["وَالْاشْتِقَاقُ رَدُّكَ اللَّفْظَ إِلى","لَفظٍ وَأَطْلِقْ فِي الَّذِيْ تَأَصَّلَا"],["وَفِي الْمَعَانِي وَالْأُصُولِ اشْتَرِطَا","تَنَاسُبًا بَيْنَهُمَا مُنْضَبِطَا"],["لَابُدَّ فِي الْمُشْتَقِّ مِنْ تَغْيِيرِ","مُحَقَّقٍ أَوْ كَانَ ذَا تَقْدِيرِ"],["وَإِنْ يَكُنْ لِمُبْهَمٍ فَقَدْ عُهِدْ","مُطَّرِدًا وَغَيْرُهُ لَا يَطَّرِدْ"],["وَالْجَبْذُ وَالْجَذْبُ كَبِيرٌ وَيَرَى","لِلْأَكْبَرِ الثَّلْمَ وَثَلْبًا مَنْ دَرَى"],["وَالْأَعْجَمِيُّ فِيهِ الِاشْتِقَاقُ","كَجَبْرَئِيلَ قَالَهُ الْحُذَّاقُ"],["كَذَا اشْتِقَاقُ الْجَمْعِ مِمَّا أُفْرِدَا","وَنَفْيُ شَرْطِ مَصْدَرٍ قَدْ عُهِدَا"],["وَعِنْدَ فَقْدِ الْوَصْفِ لَا يُشْتَقُّ","وَأَعْوَزَ الْمُعْتَزِلِيُّ الْحَقَّ"],["وَحَيْثُمَا ذُو الِاسْمِ قَامَ قَدْ وَجَبْ","وَفَرْعُهُ إِلَى الْحَقِيقَةِ انْتَسَبْ"],["لَدَى بَقَاءِ الَاصْلِ فِي الْمَحَلِّ","بِحَسَبِ الْإِمْكَانِ عِنْدَ الْجُلِّ"],["ثَالِثُهَا الْإِجْمَاعُ حَيْثُمَا طَرَا","عَلَى الْمَحَلِّ مَا مُنَاقِضًا يُرَى"],["عَلَيْهِ يُبْنَى مَنْ رَمَى الْمُطَلَّقَهْ","فَبَعْضُهُمْ نَفَى وَبَعْضٌ حَقَّقَهْ"],["فَمَا كَسَارِقٍ لَدَى الْمُؤَسِّسِ","حَقِيقَةٌ فِي حَالَةِ التَّلَبُّسِ"],["أَوْ حَالَةِ النُّطْقِ بِمَا جَا مُسْنَدَا","وَغَيْرُهُ الْعُمُومُ فِيهِ قَدْ بَدَا"],["وَذُو التَّرَادُفِ لَهُ حُصُولُ","وَقِيلَ لَا ثَالِثُهَا التَّفْصِيلُ"],["وَهَلْ يُفِيدُ التَّالِي لِلتَّأْيِيدِ","كَالنَّفْيِ لِلْمَجَازِ بِالتَّوْكِيدِ"],["وَلِلرَّدِيفَيْنِ تَعَاوُرٌ بَدَا","إِنْ لَمْ يَكُنْ بِوَاحِدٍ تَعَبَّدَا"],["وَبَعْضُهُمْ نَفْيَ الْوُقُوعِ أَبَّدَا","وَبَعْضُهُمْ بِلُغَتَيْنِ قَيَّدَا"],["دُخُولُ مَنْ عَجَزَ فِي الْإِحْرَامِ","بِمَا بِهِ الدُّخُولُ فِي الْإِسْلَامِ"],["أَوْ نِيَّةٍ أَوْ بِاللِّسَانِ يَقْتَدِي","وَالْخُلْفُ فِي التَّرْكِيبِ لَا فِي الْمُفْرَدِ"],["إِبْدَالُ قُرْآنٍ بِالْأَعْجَمِيِّ","جَوَازُهُ لَيْسَ بِمَذْهَبِيِّ"],["فِي رَأْيِ الْأَكْثَرِ وُقُوعُ الْمُشْتَرَكْ","وَثَالِثٌ لِلْمَنْعِ فِي الْوَحْيِ سَلَكْ"],["إِطْلَاقَهُ فِي مَعْنَيَيْهِ مَثَلَا","مَجَازًا أَوْ ضِدًّا أَجَازَ النُّبَلَا"],["إِنْ يَخْلُ مِنْ قَرِينَةٍ فَمُجْمَلُ","وَبَعْضُهُمْ عَلَى الْجَمِيعِ يَحْمِلُ"],["وَقِيلَ لَمْ يُجِزْهُ نَهْجُ الْعُرْبِ","وَقِيلَ بِالْمَنْعِ لِضِدِّ السَّلْبِ"],["وَفِي الْمَجَازَيْنِ أَوِ الْمَجَازِ","وَضِدِّهِ الْإِطْلَاقُ ذُو جَوَازِ"],["مِنْهَا الَّتِي لِلشَّرْعِ عَزْوُهَا عُقِلْ","مُرْتَجَلٌ مِنْهَا وَمِنْهَا مُنْتَقِلْ"],["وَالْخُلْفُ فِي الْجَوَازِ وَالْوُقُوعِ","لَهَا مِنَ الْمَأْثُوْرِ وَالْمَسْمُوعِ"],["وَمَا أَفَادَ لِاسْمِهِ النَّبِيُّ","لَا الْوَضْعُ مُطْلَقًا هُوَ الشَّرْعِيُّ"],["وَرُبَّمَا أُطْلِقَ فِي الْمَأْذُونِ","كَالشُّرْبِ وَالْعِشَاءِ وَالْعِيدَيْنِ"],["وَمِنْهُ جَائِزٌ وَمَا قَدْ مَنَعُوا","وَكُلُّ وَاحِدٍ عَلَيْهِ أَجْمَعُوا"],["مَاذَا اتِّحَادٍ فِيهِ جَاءَ الْمَحْمَلُ","وَلِلْعَلَاقَةِ ظُهُورٌ أَوَّلُ"],["ثَانِيهِمَا مَا لَيْسَ بِالْمُفِيدِ","لِمَنْعِ الِانْتِقَالِ بِالتَّعْقِيدِ"],["وَحَيْثُمَا اسْتَحَالَ الَاصْلُ يُنْتَقَلْ","إِلَى الْمَجَازِ أَوْ لِأَقْرَبَ حَصَلْ"],["وَلَيْسَ بِالْغَالِبِ فِي اللُّغَاتِ","وَالْخُلْفُ فِيهِ لِابْنِ جِنِّي آتِ"],["وَبَعْدَ تَخْصِيصٍ مَجَازٌ فَيَلِي","الِاضْمَارُ فَالنَّقْلُ عَلَى الْمُعَوَّلِ"],["فَالِاشْتِرَاكُ بَعْدَهُ النَّسْخُ جَرَى","لِكَوْنِهِ يُحْتَاطُ فِيهِ أَكْثَرَا"],["وَحَيْثُمَا قَصْدُ الْمَجَازِ قَدْ غَلَبْ","تَعْيِينُهُ لَدَى الْقَرَافِي مُنْتَخَبْ"],["وَمَذْهَبُ النُّعْمَانِ عَكْسُ مَا مَضَى","وَالْقَوْلُ بِالْإِجْمَالِ فِيهِ مُرْتَضَى"],["أَجْمَعَ إِنْ حَقِيْقَةٌ تُمَاتُ","عَلَى التَّقَدُّمِ لَهُ الأَثْبَاتُ"],["وَهُوَ حَقِيْقَةٌ أَوْ الْمَجَازُ","وَبِاعْتِبَارَيْنِ يَجِي الْجَوَازُ"],["وَاللَّفْظُ مَحْمُوْلٌ عَلى الشَّرْعِيّ","إِنْ لَّمْ يَكُنْ فَمُطْلَقُ الْعُرْفِيّ"],["فَاللُّغَوِيُّ عَلى الْجَلِيِّ وَلَمْ يَجِبْ","بَحْثٌ عَنِ الْمَجَازِ فِي الَّذِي انْتُخِبْ"],["كَذَاكَ مَا قَابَلَ ذَا اعْتِلَالِ","مِنَ التَّأَصُّلِ وَالِاسْتِقْلَالِ"],["وَمِنْ تَأَسُّسٍ عُمُومٍ وَبَقَا","الَافْرَادُ وَالْإِطْلَاقِ مِمَّا يُنْتَقَى"],["كَذَاكَ تَرْتِيْبٌ لِإِيْجَابٍ الْعَمَلْ","بِمَا لَهُ الرُّجْحَانُ مِمَّا يُحْتَمَلْ"],["وَإِنْ يَجِي الدَّلِيلُ لِلْخِلَافِ","فَقَدِّمَنَّهُ بِلَا اخْتِلَافِ"],["وَبِالتَّبَادُرِ يُرَى الْأَصِيلُ","إِنْ لَمْ يَكُ الدَّلِيلُ لَا الدَّخِيلُ"],["وَعَدَمِ النَّفْيِ وَالِاطِّرَادِ","إِنْ وُسِمَ اللَّفْظُ بِالِانْفِرَادِ"],["وَالضِّدُّ بِالْوَقْفِ فِي الِاسْتِعْمَالِ","وَكَوْنِ الِاطْلَاقِ عَلَى الْمُحَالِ"],["وَوَاجِبِ الْقَيْدِ وَمَا قَدْ جُمِعَا","مُخَالِفَ الْأَصْلِ مَجَازًا سُمِعَا"],["مَا اسْتَعْمَلَتْ فِيمَا لَهُ جَا الْعَرَبُ","فِي غَيْرِ مَا لُغَتِهِمْ مُعَرَّبُ"],["مَا كَانَ مِنْهُ مِثْلُ إِسْمَاعِيلِ","وَيُوسُفٍ قَدْ جَاءَ فِي التَّنْزِيلِ"],["إِنْ كَانَ مِنْهُ وَاعْتِقَادُ الْأَكْثَرِ","وَالشَّافِعِيِّ النَّفْيُ لِلْمُنَكَّرِ"],["وَذَاكَ لَا يُبْنَى عَلَيْهِ فَرْعُ","حَتَّى أَبَى رُجُوعَ دَرٍّ ضَرْعُ"],["مُسْتَعْمَلٌ فِي لَازِمٍ لِمَا وُضِعْ","لَهُ وَلَيْسَ قَصْدُهُ بِمُمْتَنِعْ"],["فَاسْم الْحَقِيْقَةَ وَضِدٍّ يَنْسَلِبْ","وَقِيْلَ بَلْ حَقِيْقَةٌ لِمَا يَجِبْ"],["مِنْ كَوْنِه فِيْمَا لَهُ مُسْتَعْمَلَا","وَالْقَوْلُ بِالْمَجَازِ فِيْهِ انْتُقِلَا"],["لِأَجْلِ الْاسْتِعْمَالِ فِي كِلَيْهِمَا","وَالتَّاجُ لِلْفَرْعِ وَالْاصْلِ قَسَّمَا"],["مُسْتَعْمَلٌ فِيْ أَصْلِه يُرَادُ","لَازِمُهُ مِنْهُ وَيُسْتَفَادُ"],["حَقِيقَةٌ وَحَيْثُ الْأَصْلُ مَا قُصِدْ","بَلْ لَازِمٌ فَذَاكَ أَوَّلًا وُجِدْ"],["وَسَمِّ بِالتَّعْرِيْضِ مَا اسْتُعْمِلَ فِيْ","أَصْلٍ أَوِ الْفَرْعِ لِتَلْوِيْحٍ يَفِيْ"],["لِلْغَيْرِ مِنْ مَعُونَةِ السِّيَاقِ","وَهْوَ مُرَكَّبٌ لَدَى السُّبَّاقِ"],["هُوَ اقْتِضَاءُ فِعْلِ غَيْرِ كَفِّ","دُلَّ عَلَيْهِ لَا بِنَحْوِ كُفِّي"],["هَذَا الَّذِي حُدَّ بِهِ النَّفْسِيُّ","وَمَا عَلَيْهِ دَلَّ قُلْ لَفْظِيُّ"],["وَلَيْسَ عِنْدَ جُلِّ الَاذْكِيَاءِ","شَرْطُ عُلُوٍّ فِيهِ وَاسْتِعْلَاءِ"],["وَخَالَفَ الْبَاجِي بِشَرْطِ التَّالِي","وَشَرْطُ ذَاكَ رَأْيُ ذِي اعْتِزَالِ"],["وَاعْتُبِرَا مَعًا عَلَى تَوْهِينِ","لَدَى الْقُشَيْرِيِّ وَذِي التَّلْقِينِ"],["وَالْأَمْرُ فِي الْفِعْلِ مَجَازٌ وَاعْتَمَى","تَشْرِيكَ ذَيْنِ فِيهِ بَعْضُ الْعُلَمَا"],["وَافْعَلْ لَدَى الْأَكْثَرِ لِلْوُجُوبِ","وَقِيلَ لِلنَّدْبِ أَوِ الْمَطْلُوبِ"],["وَقِيلَ لِلْوُجُوبِ أَمْرُ الرَّبِّ","وَأَمْرُ مَنْ أَرْسَلَهُ لِلنَّدْبِ"],["وَمُفْهِمُ الْوُجُوبِ يُدْرِي الشَّرْعُ","أَوِ الْحِجَا أَوِ الْمُفِيدُ الْوَضْعُ"],["وَكَوْنُهُ لِلْفَوْرِ أَصْلُ الْمَذْهَبِ","وَهْوَ لَدَى الْقَيْدِ بِتَأْخِيرٍ أُبِي"],["وَهَلْ لَدَى التَّرْكِ وُجُوبُ الْبَدَلِ","بِالنَّصِّ أَوْ ذَاكَ بِنَفْسِ الْأَوَّلِ"],["وَقَالَ بِالتَّأْخِيرِ أَهْلُ الْمَغْرِبِ","وَفِي التَّبَادُرِ حُصُولُ الْأَرَبِ"],["وَالْأَرْجَحُ الْقَدْرُ الَّذِي يُشْتَرَكُ","فِيهِ وَقِيلَ إِنَّهُ مُشْتَرَكُ"],["وَقِيلَ لِلْفَوْرِ أَوِ الْعَزْمِ وَإِنْ","نَقُلْ بِتَكْرَارٍ فَوَفْقٌ قَدْ زُكِنْ"],["وَهَلْ لِمَرَّةٍ أَوِ إطْلَاقٍ جَلَا","أَوِ التَّكَرُّرِ اخْتِلَافُ مَنْ خَلَا"],["أَوِ التَّكَرُّرُ إِذَا مَا عُلِّقَا","بِشَرْطٍ أَوْ بِصِفَةٍ تَحَقَّقَا"],["وَالْأَمْرُ لَا يَسْتَلْزِمُ الْقَضَاءَ","بَلْ هُوَ بِالْأَمْرِ الْجَدِيدِ جَاءَ"],["لِأَنَّهُ فِي زَمَنٍ مُعَيَّنِ","يَجِي لِمَا عَلَيْهِ مِنْ نَفْعٍ بُنِي"],["وَخَالَفَ الرَّازِي إِذِ الْمُرَكَّبُ","لِكُلِّ جُزْءٍ حُكْمُهُ يَنْسَحِبُ"],["وَلَيْسَ مَنْ أَمَرَ بِالْأَمْرِ أَمَرْ","لِثَالِثٍ إِلَّا كَمَا فِي ابْنِ عُمَرْ"],["وَالْأَمْرُ لِلصِّبْيَانِ نَدْبُهُ نُمِي","لِمَا رَوَوْهُ مِنْ حَدِيثِ خَثْعَمِ"],["تَعْلِيقُ أَمْرِنَا بِالِاخْتِيَارِ","جَوَازُهُ رُوِيَ بِاسْتِظْهَارِ"],["وَآمِرٌ بِلَفْظَةٍ تَعُمُّ هَلْ","دَخَلَ قَصْدًا أَوْ عَنِ الْقَصْدِ اعْتَزَلْ"],["أَنِبْ إِذَا مَا سِرُّ حُكْمٍ قَدْ جَرَى","بِهَا كَسَدِّ خَلَّةٍ لِلْفُقَرَا"],["وَالْأَمْرُ ذُو النَّفْسِ بِمَا تَعَيَّنَا","وَوَقْتُهُ مُضَيَّقٌ تَضَمَّنَا"],["نَهْيًا عَنِ الْمَوْجُودِ مِنْ أَضْدَادِ","أَوْ هُوَ نَفْسُ النَّهْيِ عَنْ أَنْدَادِ"],["وَبِتَضَمُّنِ الْوُجُوبِ فَرَّقَا","بَعْضٌ وَقِيلَ لَا يَدُلُّ مُطْلَقَا"],["فَفَاعِلٌ فِي كَالصَّلَاةِ ضِدَّا","كَسِرْقَةٍ عَلَى الْخِلَافِ يُبْدَى"],["إِلَّا إِذَا النَّصُّ الْفَسَادَ أَبْدَى","مِثْلُ الْكَلَامِ فِي الصَّلَاةِ عَمْدَا"],["وَالنَّهْيُ فِيهِ غَابِرُ الْخِلَافِ","أَوْ أَنَّهُ أَمْرٌ عَلَى ائْتِلَافِ"],["وَقِيلَ لَا قَطْعًا كَمَا فِي الْمُخْتَصَرْ","وَهْوَ لَدَى السُّبْكِيِّ رَأْيٌ مَا انْتَصَرْ"],["الَامْرَانِ غَيْرُ الْمُتَمَاثِلَيْنِ","عُدَّا كَصُمْ نَمْ مُتَغَايِرَيْنِ"],["وَإِنْ تَمَاثَلَا وَعَطْفٌ قَدْ نُفِي","بِلَا تَعَاقُبٍ فَتَأْسِيسٌ قُفِي"],["وَإِنْ تَعَاقَبَا فَذَا هُوَ الْأَصَحّْ","وَالضَّعْفُ لِلتَّأْكِيدِ وَالْوَقْفِ وَضَحْ"],["إِنْ لَمْ يَكُنْ تَأَسُّسٌ ذَا مَنْعِ","مِنْ عَادَةٍ وَمِنْ حِجًا وَشَرْعِ"],["وَإِنْ يَكُنْ عَطْفٌ فَتَأْسِيسٌ بِلَا","مَنْعٍ يُرَى لَدَيْهِمُ مُعَوَّلَا"],["وَالْأَمْرُ لِلْوُجُوبِ بَعْدَ الْحَظْلِ","وَبَعْدَ سُؤْلٍ قَدْ أَتَى لِلْأَصْلِ"],["أَوْ يَقْتَضِي إِبَاحَةً لِلْأَغْلَبِ","إِذَا تَعَلَّقَ بِمِثْلِ السَّبَبِ"],["إِلَّا فَذِي الْمَذْهَبُ وَالْكَثِيرُ","لَهُ إِلَى إِيجَابِهِ مَصِيرُ"],["بَعْدَ الْوُجُوبِ النَّهْيُ لِامْتِنَاعِ","لِلْجُلِّ وَالْبَعْضُ لِلِاتِّسَاعِ"],["وَلِلْكَرَاهَةِ بِرَأْيٍ بَانَا","وَقِيلَ لِلْإِبْقَا عَلَى مَا كَانَا"],["كَالنَّسْخِ لِلْوُجُوبِ عِنْدَ الْقَاضِي","وَجُلُّنَا بِذَاكَ غَيْرُ رَاضِ"],["بَلْ هُوَ فِي الْقَوِيِّ رَفْعُ الْحَرَجِ","وَلِلْإِبَاحَةِ لَدَى بَعْضٍ يَجِي"],["وَقِيلَ لِلنَّدْبِ كَمَا فِي مُبْطِلِ","أَوْجَبَ الِانْتِقَالَ لِلتَّنَفُّلِ"],["وَجُوِّزَ التَّكْلِيفُ بِالْمُحَالِ","فِي الْكُلِّ مِنْ ثَلَاثَةِ الْأَحْوَالِ"],["وَقِيلَ بِالْمَنْعِ لِمَا قَدِ امْتَنَعْ","لِغَيْرِ عِلْمِ اللَّهِ أَنْ لَيْسَ يَقَعْ"],["وَلَيْسَ وَاقِعًا إِذَا اسْتَحَالَا","لِغَيْرِ عِلْمِ رَبِّنَا تَعَالَى"],["وَمَا وُجُودُ وَاجِبٍ قَدْ أُطْلِقَا","بِهِ وُجُوبُهُ بِهِ تَحَقَّقَا"],["وَالطَّوْقُ شَرْطٌ لِلْوُجُوبِ يُعْرَفُ","إِنْ كَانَ بِالْمُحَالِ لَا يُكَلَّفُ"],["كَعِلْمِنَا الْوُضُوءَ شَرْطًا فِي أَدَا","فَرْضٍ فَأَمْرُنَا بِهِ بَعْدُ بَدَا"],["وَبَعْضُ ذِي الْخُلْفِ نَفَاهُ مُطْلَقَا","وَالْبَعْضُ ذُو رَأْيَيْنِ قَدْ تَفَرَّقَا"],["وَمَا وُجُوبُهُ بِهِ لَمْ يَجِبِ","فِي رَأْيِ مَالِكٍ وَكُلِّ مَذْهَبِ"],["فَمَا بِهِ تَرْكُ الْمُحَرَّمِ يَرَى","وُجُوبَ تَرْكِهِ جَمِيعُ مَنْ دَرَى"],["وَسَوِّيَنَّ بَيْنَ جَهْلٍ لَحِقَا","بَعْدَ التَّعَيُّنِ وَمَا قَدْ سَبَقَا"],["هَلْ يَجِبُ التَّنْجِيزُ فِي التَّمَكُّنِ","أَوْ مُطْلَقُ التَّمْكِينِ ذُو تَعَيُّنِ"],["عَلَيْهِ فِي التَّكْلِيفِ بِالشَّيْءِ عُدِمْ","مُوجِبُهُ شَرْعًا خِلَافٌ قَدْ عُلِمْ"],["فَالْخُلْفُ فِي الصِّحَّةِ وَالْوُقُوعِ","لِأَمْرِ مَنْ كَفَرَ بِالْفُرُوعِ"],["ثَالِثُهَا الْوُقُوعُ فِي النَّهْيِ يُرَدّْ","بِمَا افْتِقَارُهُ إِلَى الْقَصْدِ انْفَقَدْ"],["وَقِيلَ فِي الْمُرْتَدِّ فَالتَّعْذِيبُ","عَلَيْهِ وَالتَّيْسِيرُ وَالتَّرْغِيبُ"],["وَعُلِّلَ الْمَانِعُ بِالتَّعَذُّرِ","وَهْوَ مُشْكِلٌ لَدَى الْمُحَرِّرِ"],["فِي كَافِرٍ آمَنَ مُطْلَقًا وَفِي","مَنْ كُفْرُهُ فِعْلٌ كَإِلْقَا مُصْحَفِ"],["وَالرَّأْيُ عِنْدِي أَنْ يَكُونَ الْمُدْرَكُ","نَفْيَ قَبُولِهَا فَذَا مُشْتَرَكُ"],["تَكْلِيفُ مَنْ أَحْدَثَ بِالصَّلَاةِ","عَلَيْهِ مُجْمَعٌ لَدَى الثِّقَاتِ"],["وَرَبْطُهُ بِالْمُوجِبِ الْعَقْلِيِّ","حَتْمٌ بِوَفْقٍ قَدْ أَتَى جَلِيِّ"],["دُخُولُ ذِي كَرَاهَةٍ فِيمَا أُمِرْ","بِهِ بِلَا قَيْدٍ وَفَصْلٍ قَدْ حُظِرْ"],["فَنَفْيُ صِحَّةٍ وَنَفْيُ الْأَجْرِ","فِي وَقْتِ كُرْهٍ لِلصَّلَاةِ يَجْرِي"],["وَإِنْ يَكُ الْأَمْرُ عَنِ النَّهْيِ انْفَصَلْ","فَالْفِعْلُ بِالصِّحَّةِ لَا الْأَجْرِ اتَّصَلْ"],["وَذَا إِلَى الْجُمْهُورِ ذُو انْتِسَابِ","وَقِيلَ بِالَاجْرِ مَعَ الْعِقَابِ"],["وَقَدْ رُوِي الْبُطْلَانُ وَالْقَضَاءُ","وَقِيلَ ذَا فَقَطْ لَهُ انْتِفَاءُ"],["مِثْلُ الصَّلَاةِ بِالْحَرِيرِ وَالذَّهَبْ","أَوْ فِي مَكَانِ الْغَصْبِ وَالْوُضُو انْقَلَبْ"],["وَمَعْطِنٍ وَمَنْهَجٍ وَمَقْبَرَهْ","كَنِيسَةٍ وَذِي حَمِيمٍ مَجْزَرَهْ"],["مَنْ تَابَ بَعْدَ أَنْ تَعَاطَى السَّبَبَا","فَقَدْ أَتَى بِمَا عَلَيْهِ وَجَبَا"],["وَإِنْ بَقِي فَسَادُهُ كَمَنْ رَجَعْ","عَنْ بَثِّ بِدْعَةٍ عَلَيْهَا يُتَّبَعْ"],["أَوْ تَابَ خَارِجًا مَكَانَ الْغَصْبِ","أَوْ تَابَ بَعْدَ الرَّمْيِ قَبْلَ الضَّرْبِ"],["وَقَالَ ذُو الْبُرْهَانِ إِنَّهُ ارْتَبَكْ","مَعَ انْقِطَاعِ النَّهْيِ لِلَّذِي سَلَكْ"],["وَارْتَكِبِ الْأَخَفَّ مِنْ ضُرَّيْنِ","وَخَيِّرَنْ لَدَى اسْتِوَا هَذَيْنِ"],["كَمَنْ عَلَى الْجَرِيحِ فِي الْجَرْحَى سَقَطْ","وَضَعَّفَ الْمُكْثَ عَلَيْهِ مَنْ ضَبَطْ"],["وَالْأَخْذُ بِالْأَوَّلِ لَا بِالْآخِرِ","مُرَجَّحٌ فِي مُقْتَضَى الْأَوَامِرِ"],["وَمَا سِوَاهُ سَاقِطٌ أَوْ مُسْتَحَبّْ","لِذَاكَ الِاطْمِئْنَانُ وَالدَّلْكُ انْجَلَبْ"],["وَذَاكَ فِي الْحُكْمِ عَلَى الْكُلِّيِّ","مَعَ حُصُولِ كَثْرَةِ الْجُزْئِيِّ"],["وَرُبَّمَا اجْتِمَاعُ أَشْيَاءَ انْحَظَلْ","مِمَّا أَتَى الْأَمْرُ بِهَا عَلَى الْبَدَلْ"],["أَوِ التَّرَتُّبِ وَقَدْ يُسَنُّ","وَفِيهِ قُلْ إِبَاحَةٌ تَعِنُّ"],["مَا وَقْتُهُ يَسَعُ مِنْهُ أَكْثَرَا","وَهْوَ مَحْدُودًا وَغَيْرَهُ جَرَى"],["فَجَوَّزُوا الْأَدَا بِلَا اضْطِرَارِ","فِي كُلِّ حِصَّةٍ مِنَ الْمُخْتَارِ"],["وَقَائِلٍ مِنَّا يَقُولُ الْعَزْمُ","عَلَى وُقُوعِ الْفَرْضِ فِيهِ حَتْمُ"],["أَوْ هُوَ مَا مُكَلَّفٌ يُعَيِّنُ","وَخُلْفُ ذِي الْخِلَافِ فِيهِ بَيِّنُ"],["فَقِيلَ الْآخِرُ وَقِيلَ الْأَوَّلُ","وَقِيلَ مَا بِهِ الْأَدَا يَتَّصِلُ"],["وَالْأَمْرُ بِالْوَاحِدِ مِنْ أَشْيَاءِ","يُوجِبُ وَاحِدًا عَلَى اسْتِوَاءِ"],["مَا طَلَبَ الشَّارِعُ أَنْ يُحَصَّلَا","دُونَ اعْتِبَارِ ذَاتِ مَنْ قَدْ فَعَلَا"],["وَهْوَ مُفَضَّلٌ عَلَى ذِي الْعَيْنِ","فِي زَعْمِ الَاسْتَاذِ مَعَ الْجُوَيْنِي"],["مِزْهُ مِنَ الْعَيْنِ بِأَنْ قَدْ حُظِلَا","تَكْرِيرُ مَصْلَحَتِهِ إِنْ فُعِلَا"],["وَهْوَ عَلَى الْجَمِيعِ عِنْدَ الْأَكْثَرِ","لِإِثْمِهِمْ بِالتَّرْكِ وَالتَّعَذُّرِ"],["وَفِعْلُ مَنْ بِهِ يَقُومُ مُسْقِطُ","وَقِيلَ بِالْبَعْضِ فَقَطْ يَرْتَبِطُ"],["مُعَيَّنًا أَوْ مُبْهَمًا أَوْ فَاعِلًا","خُلْفٌ عَنِ الْمُخَالِفِينَ نُقِلَا"],["مَا كَانَ بِالْجُزْئِيِّ نَدْبُهُ عُلِمْ","فَهْوَ بِالْكُلِّيِّ كَعِيدٍ مُنْحَتِمْ"],["وَهَلْ يُعَيِّنُ شُرُوعُ الْفَاعِلِ","فِي ذِي الْكِفَايَةِ خِلَافٌ يَنْجَلِي"],["فَالْخُلْفُ فِي الْأُجْرَةِ لِلتَّحَمُّلِ","فَرْعٌ عَلَى ذَاكَ الْخِلَافِ قَدْ بُلِي"],["وَغَالِبُ الظَّنِّ فِي الِاسْقَاطِ كَفَى","وَفِي التَّوَجُّهِ لَدَى مَنْ عُرِفَا"],["فُرُوضُهُ الْقَضَا كَنَهْيٍ أَمْرِ","رَدِّ السَّلَامِ وَجِهَادِ الْكُفْرِ"],["فَتْوَى وَحِفْظِ مَا سِوَى الْمَثَانِي","زِيَارَةِ الْحَرَامِ ذِي الْأَرْكَانِ"],["إِمَامَةٌ مِنْهُ وَدَفْعِ الضَّرَرِ","وَالِاحْتِرَافِ مَعَ سَدِّ الثُّغُرِ"],["حَضَانَةٍ تَوَثُّقٍ شَهَادَهْ","تَجْهِيزِ مَيْتٍ وَكَذَا الْعِيَادَهْ"],["ضِيَافَةٍ حُضُورِ مَنْ فِي النَّزْعِ","وَحِفْظِ سَائِرِ عُلُومِ الشَّرْعِ"],["وَغَيْرُهُ الْمَسْنُونُ كَالْإِمَامَهْ","وَالْبَدْءِ بِالسَّلَامِ وَالْإِقَامَهْ"],["هُوَ اقْتِضَاءُ الْكَفِّ عَنْ فِعْلٍ وَدَعْ","وَمَا يُضَاهِيهِ كَذَرْ قَدِ امْتَنَعْ"],["وَهْوَ لِلدَّوَامِ وَالْفَوْرِ مَتَى","عَدَمُ تَقْيِيدٍ بِضِدٍّ ثَبَتَا"],["وَاللَّفْظُ لِلتَّحْرِيمِ شَرْعًا وَافْتَرَقْ","لِلْكُرْهِ وَالشِّرْكَةِ وَالْقَدْرِ الْفِرَقْ"],["وَهْوَ عَنْ فَرْدٍ وَعَنْ مَا عُدِّدَا","جَمْعًا وَفَرْقًا وَجَمِيعًا وُجِدَا"],["وَجَاءَ فِي الصَّحِيحِ لِلْفَسَادِ","إِنْ لَمْ يَجِي الدَّلِيلُ لِلسَّدَادِ"],["لِعَدَمِ النَّفْعِ وَزَيْدِ الْخَلَلِ","وَمُلْكُ مَا بِيعَ عَلَيْهِ يَنْجَلِي"],["إِذَا تَغَيَّرَ بِسُوقٍ أَوْ بَدَنْ","أَوْ حَقُّ غَيْرِهِ بِهِ قَدِ اقْتَرَنْ"],["وَبَثَّ لِلصِّحَّةِ فِي الْمَدَارِسِ","مُعَلِّلًا بِالنَّهْيِ حِبْرُ فَارِسِ"],["وَالْخُلْفُ فِيمَا يَنْتَمِي لِلشَّرْعِ","وَلَيْسَ فِيمَا يَنْتَمِي لِلطَّبْعِ"],["الَاجْزَاءُ وَالْقَبُولُ حِينَ نُفِيَا","لِصِحَّةٍ وَضِدِّهَا قَدْ رُوِيَا"],["مَا اسْتَغْرَقَ الصَّالِحَ دَفْعَةً بِلَا","حَصْرٍ مِنَ اللَّفْظِ كَعَشْرٍ مَثَلَا"],["وَهْوَ مِنْ عَوَارِضِ الْمَبَانِي","وَقِيلَ لِلْأَلْفَاظِ وَالْمَعَانِي"],["هَلْ نَادِرٌ فِي ذِي الْعُمُومِ يَدْخُلُ","وَمُطْلَقٍ أَوْ لَا خِلَافٌ يُنْقَلُ"],["فَمَا لِغَيْرِ لَذَّةٍ وَالْفِيلُ","وَمُشْبِهٌ فِيهِ تَنَافَى الْقِيلُ"],["وَمَا مِنَ الْقَصْدِ خَلَا فِيهِ اخْتُلِفْ","وَقَدْ يَجِيءُ بِالْمَجَازِ مُتَّصِفْ"],["مَدْلُولُهُ كُلِّيَّةٌ إِنْ حَكَمَا","عَلَيْهِ فِي التَّرْكِيبِ مَنْ تَكَلَّمَا"],["وَهْوَ عَلَى فَرْدٍ يَدُلُّ حَتْمَا","وَفَهْمُ الِاسْتِغْرَاقِ لَيْسَ جَزْمَا"],["بَلْ هُوَ عِنْدَ الْجُلِّ بِالرُّجْحَانِ","وَالْقَطْعُ فِيهِ مَذْهَبُ النُّعْمَانِ"],["وَيَلْزَمُ الْعُمُومُ فِي الزَّمَانِ","وَالْحَالِ لِلْأَفْرَادِ وَالْمَكَانِ"],["إِطْلَاقُهُ فِي تِلْكَ لِلْقَرَافِي","وَعَمَّمَ التَّقِيْ إِذَا يُنَافِي"],["صِيَغُهُ كُلُّ أَوِ الْجَمِيعُ","وَقَدْ تَلَا الَّذِي الَّتِي الْفُرُوعُ"],["أَيْنَ وَحَيْثُمَا وَمَنْ أَيٌّ وَمَا","شَرْطًا وَوَصْلًا وَسُؤَالًا أَفْهَمَا"],["مَتَى وَقِيلَ لَا وَبَعْضٌ قَيَّدَا","وَمَا مُعَرَّفًا بِأَلْ قَدْ وُجِدَا"],["أَوْ بِإِضَافَةٍ إِلَى الْمُعَرَّفِ","إِذَا تَحَقُّقُ الْخُصُوصِ قَدْ نُفِي"],["وَفِي سِيَاقِ النَّفْيِ مِنْهَا يُذْكَرُ","إِذَا بُنِي أَوْ زِيْدَ مِنْ مُنَكَّرُ"],["أَوْ كَانَ صِيغَةً لَهَا النَّفْيُ لَزِمْ","وَغَيْرُ ذَا لَدَى الْقَرَافِي لَا يَعُمّْ"],["وَقِيلَ بِالظُّهُورِ فِي الْعُمُومِ","وَهْوَ مُفَادُ الْوَضْعِ لَا اللُّزُومِ"],["بِالْقَصْدِ خُصِّصِ الْتِزَامًا قَدْ أَبَى","تَخْصِيصَهُ إِيَّاهُ بَعْضُ النُّجَبَا"],["وَنَحْوُ لَا شَرِبْتُ أَوْ إِنْ شَرِبَا","وَاتَّفَقُوا إِنْ مَصْدَرٌ قَدْ جُلِبَا"],["وَنَزِّلَنَّ تَرْكَ الِاسْتِفْصَالِ","مَنْزِلَةَ الْعُمُومِ فِي الْأَقْوَالِ"],["قِيَامُ الِاحْتِمَالِ فِي الْأَفْعَالِ","قُلْ مُجْمِلٌ مُسْقِطُ الِاسْتِدْلَالِ"],["وَمَا أَتَى لِلْمَدْحِ أَوْ لِلذَّمِّ","يَعُمُّ عِنْدَ جُلِّ أَهْلِ الْعِلْمِ"],["وَمَا بِهِ قَدْ خُوطِبَ النَّبِيُّ","تَعْمِيمُهُ فِي الْمَذْهَبِ السَّنِيُّ"],["وَمَا يَعُمُّ يَشْمَلُ الرَّسُولَا","وَقِيلَ لَا وَلْنَذْكُرِ التَّفْصِيلَا"],["وَالْعَبْدُ وَالْمَوْجُودُ وَالَّذِي كَفَرْ","مَشْمُولَةٌ لَهُ لَدَى ذَوِي النَّظَرْ"],["وَمَا شُمُولُ مَنْ لِلُانْثَى جَنَفُ","وَفِي شَبِيهِ الْمُسْلِمِينَ اخْتَلَفُوا"],["وَعَمِّمِ الْمَجْمُوعَ لِلْأَنْوَاعِ","إِذَا بِمِنْ جُرَّ عَلَى نِزَاعِ"],["كَمِنْ عُلُومٍ أَلْقِ بِالتَّفْصِيلِ","لِلْفِقْهِ وَالتَّفْسِيرِ وَالْأُصُولِ"],["وَالْمُقْتَضِي أَعَمَّ جُلُّ السَّلَفِ","كَذَاكَ مَفْهُومٌ بِلَا مُخْتَلَفِ"],["مِنْهُ مُنَكَّرُ الْجُمُوعِ عُرِفَا","وَكَانَ وَالَّذِي عَلَيْهِ انْعَطَفَا"],["وَسَائِرٌ حِكَايَةُ الْفِعْلِ بِمَا","مِنْهُ الْعُمُومُ ظَاهِرًا قَدْ عُلِمَا"],["خِطَابُ وَاحِدٍ لِغَيْرِ الْحَنْبَلِي","مِنْ غَيْرِ رَعْيِ النَّصِّ وَالْقَيْسِ الْجَلِي"],["قَصْرُ الَّذِي عَمَّ مَعَ اعْتِمَادِ","غَيْرٍ عَلَى بَعْضٍ مِنَ الْأَفْرَادِ"],["جَوَازُهُ لِوَاحِدٍ فِي الْجَمْعِ","أَتَتْ بِهِ أَدِلَّةٌ فِي الشَّرْعِ"],["وَمُوجِبٌ أَقَلَّهُ الْقَفَّالُ","وَالْمَنْعُ مُطْلَقًا لَهُ اعْتِلَالُ"],["أَقَلُّ مَعْنَى الْجَمْعِ فِي الْمُشْتَهِرِ","الِاثْنَانِ فِي رَأْيِ الْإِمَامِ الْحِمْيَرِي"],["ذَا كَثْرَةٍ أَمْ لَا وَإِنْ مُنَكَّرَا","وَالْفَرْقُ فِي انْتِهَاءِ مَا قَدْ نُكِّرَا"],["وَذُو الْخُصُوصِ هُوَ مَا يُسْتَعْمَلُ","فِي كُلِّ الَافْرَادِ لَدَى مَنْ يَعْقِلُ"],["وَمَا بِهِ الْخُصُوصُ قَدْ يُرَادُ","جَعَلَهُ فِي بَعْضِهَا النُّقَّادُ"],["وَالثَّانِيَ اعْزُ لِلْمَجَازِ جَزْمَا","وَذَاكَ لِلْأَصْلِ وَفَرْعٍ يُنْمَى"],["ثُمَّ الْمُحَاشَاةُ وَقَصْرُ الْقَصْدِ","مِنْ آخِرِ الْقِسْمَيْنِ دُونَ جَحْدِ"],["وَشِبْهُ الِاسْتِثْنَا لِلَاوَّلِ سَمَا","وَاتَّحَدَ الْقِسْمَانِ عِنْدَ الْقُدَمَا"],["وَهْوَ حُجَّةٌ لَدَى الْأَكْثَرِ إِنْ","مُخَصَّصٌ لَهُ مُعَيَّنًا يَبِنْ"],["وَقِسْ عَلَى الْخَارِجِ لِلْمَصَالِحِ","وَرُبَّ شَيْخٍ لِامْتِنَاعٍ جَانِحِ"],["حُرُوفُ االِاسْتِثْنَاءِ وَالْمُضَارِعُ","مِنْ فِعْلٍ لِاسْتِثْنَا وَمَا يُضَارِعُ"],["وَالْحُكْمُ بِالنَّقِيضِ لِلْحُكْمِ حَصَلْ","لِمَا عَلَيْهِ الْحُكْمُ قَبْلُ مُتَّصِلْ"],["وَغَيْرُهُ مُنْقَطِعٌ وَرُجِّحَا","جَوَازُهُ وَهْوَ مَجَازًا وَضَحَا"],["فَلْتُنْمِ ثَوْبًا بَعْدَ أَلْفِ دِرْهَمِ","لِلْحَذْفِ وَالْمَجَازِ أَوْ لِلنَّدَمِ"],["وَقِيلَ بِالْحَذْفِ لَدَى الْإِقْرَارِ","وَالْعَقْدُ مَعْنَى الْوَاوِ فِيهِ جَارِ"],["بِشِرْكَةٍ وَبِالتَّوَاطِي قَالَا","بَعْضٌ وَأَوْجِبْ فِيهِ الِاتِّصَالَا"],["وَفِي الْبَوَاقِي دُونَ مَا اضْطِرَارِ","وَابْطِلَنْ بِالصَّمْتِ لِلتَّذْكَارِ"],["وَعَدَدٌ مَعَ كَإِلَّا قَدْ وَجَبْ","لَهُ الْخُصُوصُ عِنْدَ جُلِّ مَنْ ذَهَبْ"],["وَقَالَ بَعْضٌ بِانْتِفَا الْخُصُوصِ","وَالظَّاهِرُ الِابْقَا مِنَ النُّصُوصِ"],["وَالْمِثْلُ عِنْدَ الْأَكْثَرِينَ مُبْطِلُ","وَلِجَوَازِهِ يَدُلُّ الْمَدْخَلُ"],["وَجَوِّزِ الْأَكْثَرَ عِنْدَ الْجُلِّ","وَمَالِكٌ أَوْجَبَ لِلْأَقَلِّ"],["وَمُنِعَ الْأَكْثَرُ مِنْ نَصِّ الْعَدَدْ","وَالْعَقْدُ مِنْهُ عِنْدَ بَعْضٍ انْفَقَدْ"],["وَذَا تَعَدُّدٍ بِعَطْفٍ حَصِّلِ","بِالِاتِّفَاقِ مُسْجَلًا لِلْأَوَّلِ"],["إِلَّا فَكُلٌّ لِلَّذِي بِهِ اتَّصَلْ","وَكُلُّهَا عِنْدَ التَّسَاوِي قَدْ بَطَلْ"],["إِنْ كَانَ غَيْرُ الَاوَّلِ الْمُسْتَغْرِقَا","فَالْكُلُّ لِلْمُخْرَجِ مِنْهُ حُقِّقَا"],["وَحَيْثُمَا اسْتَغْرَقَ الَاوَّلُ فَقَطْ","فَأَلْغِ وَاعْتَبِرْ بِخَلْفٍ فِي النَّمَطْ"],["وَكُلُّ مَا يَكُونُ فِيهِ الْعَطْفُ","مِنْ قَبْلِ الِاسْتِثْنَا فَكُلًّا يَقْفُو"],["دُونَ دَلِيلِ الْعَقْلِ أَوْ ذِي السَّمْعِ","وَالْحَقُّ الِافْتِرَاقُ دُونَ الْجَمْعِ"],["أَمَّا قِرَانُ اللَّفْظِ فِي الْمَشْهُورِ","فَلَا يُسَاوِي فِي سِوَى الْمَذْكُورِ"],["وَمِنْهُ مَا كَانَ مِنَ الشَّرْطِ أَعِدْ","لِلْكُلِّ عِنْدَ الْجُلِّ أَوْ وَفْقًا تُفِدْ"],["أَخْرِجْ بِهِ وَإِنْ عَلَى النِّصْفِ سَمَا","كَالْقَوْمَ أَكْرِمْ إِنْ يَكُونُوا كُرَمَا"],["وَإِنْ تَرَتَّبَ عَلَى شَرْطَيْنِ","شَيْءٌ فَبِالْحُصُولِ لِلشَّرْطَيْنِ"],["وَإِنْ عَلَى الْبَدَلِ قَدْ تَعَلَّقَا","فَبِحُصُولِ وَاحِدٍ تُحُقِّقَا"],["وَمِنْهُ فِي الْإِخْرَاجِ وَالْعَوْدِ يُرَى","كَالشَّرْطِ قُلْ وَصْفٌ وَإِنْ قَبْلُ جَرَى"],["وَحَيْثُمَا مُخَصِّصٌ تَوَسَّطَا","خَصَّصَهُ بِمَا يَلِي مَنْ ضَبَطَا"],["وَمِنْهُ غَايَةُ عُمُومٍ يَشْمُلُ","لَوْ كَانَ تَصْرِيحٌ بِهَا لَا يَحْصُلُ"],["وَمَا لِتَحْقِيقِ الْعُمُومِ فَدَعِ","نَحْوُ سَلَامٌ هِيَ حَتَّى مَطْلَعِ"],["وَهْيَ لِمَا قَبْلُ خَلَا تَعُودُ","وَكَوْنُهَا لِمَا تَلِي بَعِيدُ"],["وَبَدَلُ الْبَعْضِ مِنَ الْكُلِّ يَفِي","مُخَصِّصًا لَدَى انَاسٍ فَاعْرِفِ"],["وَسَمِّ مُسْتَقِلَّهُ مُنْفَصِلَا","لِلْحِسِّ وَالْعَقْلِ نَمَاهُ الْفُضَلَا"],["وَخَصِّصِ الْكِتَابَ وَالْحَدِيثَ بِهْ","أَوْ بِالْحَدِيثِ مُطْلَقًا فَلْتَنْتَبِهْ"],["وَاعْتَبَرَ الْإِجْمَاعَ جُلُّ النَّاسِ","وَقِسْمَيِ الْمَفْهُومِ كَالْقِيَاسِ"],["وَالْعُرْفَ حَيْثُ قَارَنَ الْخِطَابَا","وَدَعْ ضَمِيرَ الْبَعْضِ وَالَاسْبَابَا"],["وَذِكْرَ مَا وَافَقَهُ مِنْ مُفْرَدِ","وَمَذْهَبَ الرَّاوِي عَلَى الْمُعْتَمَدْ"],["وَاجْزِمْ بِإِدْخَالِ ذَوَاتِ السَّبَبِ","وَارْوِ عَنِ الْإِمَامِ ظَنًّا تُصِبِ"],["وَجَاءَ فِي تَخْصِيصِ مَا قَدْ جَاوَرَا","فِي الرَّسْمِ مَا يَعُمُّ خُلْفُ النُّظَرَا"],["وَإِنْ أَتَى مَا خَصَّ بَعْدَ الْعَمَلِ","نَسَخَ وَالْغَيْرُ مُخَصِّصًا جَلِي"],["وَإِنْ يَكُ الْعُمُومُ مِنْ وَجْهٍ ظَهَرْ","فَالْحُكْمُ بِالتَّرْجِيحِ حَتْمًا مُعْتَبَرْ"],["فَمَا عَلَى مَعْنَاهُ زِيدَ مُسْجَلَا","مَعْنًى لِغَيْرِهِ اعْتَقِدْهُ الْأَوَّلَا"],["وَمَا عَلَى الذَّاتِ بِلَا قَيْدٍ يَدُلّْ","فَمُطْلَقٌ وَبِاسْمِ جِنْسٍ قَدْ عُقِلْ"],["وَمَا عَلَى الْوَاحِدِ شَاعَ النَّكِرَهْ","وَالِاتِّحَادُ بَعْضُهُمْ قَدْ نَصَرَهْ"],["عَلَيْهِ طَالِقٌ إِذَا كَانَ ذَكَرْ","فَوَلَدَتْ لِاثْنَيْنِ عِنْدَ ذِي النَّظَرْ"],["بِمَا يُخَصِّصُ الْعُمُومَ قَيِّدِ","وَدَعْ لِمَا كَانَ سِوَاهُ تَقْتَدِي"],["وَحَمْلُ مُطْلَقٍ عَلَى ذَاكَ وَجَبْ","إِنْ فِيهِمَا اتَّحَدَ حُكْمٌ وَالسَّبَبْ"],["وَإِنْ يَكُنْ تَأَخَّرَ الْمُقَيَّدُ","عَنْ عَمَلٍ فَالنَّسْخُ فِيهِ يُعْهَدُ"],["وَإِنْ يَكُنَ امْرٌ وَنَهْيٌ قُيِّدَا","فَمُطْلَقٌ بِضِدِّ مَا قَدْ وُجِدَا"],["وَحَيْثُمَا اتَّحَدَ وَاحِدٌ فَلَا","يَحْمِلُهُ عَلَيْهِ جُلُّ الْعُقَلَا"],["حَمْلٌ لِظَاهِرٍ عَلَى الْمَرْجُوحِ","وَاقْسِمْهُ لِلْفَاسِدِ وَالصَّحِيحِ"],["صَحِيحُهُ وَهْوَ الْقَرِيبُ مَا حُمِلْ","مَعْ قُوَّةِ الدَّلِيلِ عِنْدَ الْمُسْتَدِلّْ"],["وَغَيْرُهُ الْفَاسِدُ وَالْبَعِيدُ","وَمَا خَلَا فَلَعِبًا يُفِيدُ"],["وَالْخُلْفَ فِي فَهْمِ الْكِتَابِ صَيِّرِ","إِيَّاهُ تَأْوِيلًا لَدَى الْمُخْتَصَرِ"],["فَجَعْلُ مِسْكِينٍ بِمَعْنَى الْمُدِّ","عَلَيْهِ لَائِحٌ سِمَاةُ الْبُعْدِ"],["كَحَمْلِ مَرْأَةٍ عَلَى الصَّغِيرَهْ","وَمَا يُنَافِي الْحُرَّةَ الْكَبِيرَهْ"],["وَحَمْلِ مَا رُوِيَ فِي الصِّيَامِ","عَلَى الْقَضَاءِ مَعَ الِالْتِزَامِ"],["وَذُو وُضُوحٍ مُحْكَمٌ وَالْمُجْمَلُ","هُوَ الَّذِي الْمُرَادُ مِنْهُ يُجْهَلُ"],["وَمَا بِهِ اسْتَأْثَرَ عِلْمُ الْخَالِقِ","فَذَا تَشَابُهٍ عَلَيْهِ أَطْلِقِ"],["وَإِنْ يَكُنْ عِلْمٌ بِهِ مِنْ عَبْدِ","فَذَاكَ لَيْسَ مِنْ طَرِيقِ الْعَهْدِ"],["وَقَدْ يَجِي الْإِجْمَالُ مِنْ وَجْهٍ وَمِنْ","وَجْهٍ يَرَاهُ ذَا بَيَانٍ مَنْ فَطِنْ"],["وَالنَّفْيُ لِلصَّلَاةِ وَالنِّكَاحِ","وَالشَّبْهِ مُحْكَمٌ لَدَى الصِّحَاحِ"],["وَالْعَكْسُ فِي جِدَارِهِ وَيَعْفُو","وَالْقَرْءِ فِي مَنْعِ اجْتِمَاعٍ فَاقْفُوا"],["تَصْيِيرُ مُشْكِلٍ مِنَ الْجَلِيِّ","وَهْوَ وَاجِبٌ عَلَى النَّبِيِّ"],["إِذَا أُرِيدَ فَهْمُهُ وَهُوَ بِمَا","مِنَ الدَّلِيلِ مُطْلَقًا يَجْلُو الْعَمَى"],["وَبَيَّنَ الْقَاصِرُ مِنْ حَيْثُ السَّنَدْ","أَوِ الدَّلَالَةُ عَلَى مَا يُعْتَمَدْ"],["وَأَوْجِبَنَّ عِنْدَ بَعْضٍ عِلْمًا","إِذَا وُجُوبُ ذِي الْخَفَاءِ عَمَّا"],["وَالْقَوْلُ وَالْفِعْلُ إِذَا تَوَافَقَا","فَانْمِ الْبَيَانَ لِلَّذِي قَدْ سَبَقَا"],["وَإِنْ يَزِدْ فِعْلٌ فَلِلْقَوْلِ انْتَسِبْ","وَالْفِعْلُ يَقْتَضِي بِلَا قَيْدٍ طَلَبْ"],["وَالْقَوْلُ فِي الْعَكْسِ هُوَ الْمُبَيِّنُ","وَفِعْلُهُ التَّخْفِيفُ فِيهِ بَيِّنُ"],["تَأَخُّرُ الْبَيَانِ عَنْ وَقْتِ الْعَمَلْ","وُقُوعُهُ عِنْدَ الْمُجِيزِ مَا حَصَلْ"],["تَأْخِيرُهُ لِلِاحْتِيَاجِ وَاقِعُ","وَبَعْضُنَا هُوَ لِذَاكَ مَانِعُ"],["وَقِيلَ بِالْمَنْعِ بِمَا كَالْمُطْلَقِ","ثُمَّ بِعَكْسِهِ لَدَى الْبَعْضِ انْطِقِ"],["وَجَائِزٌ تَأْخِيرُ تَبْلِيغٍ لَهُ","وَدَرْءُ مَا يُخْشَى أَبَى تَعْجِيلَهُ"],["وَنِسْبَةُ الْجَهْلِ لِذِي وُجُودِ","بِمَا يُخَصِّصُ مِنَ الْمَوْجُودِ"],["رَفْعٌ لِحُكْمٍ أَوْ بَيَانُ الزَّمَنِ","بِمُحْكَمِ الْقُرْآنِ أَوْ بِالسُّنَنِ"],["فَلَمْ يَكُنْ بِالْعَقْلِ أَوْ مُجَرَّدِ","الِاجْمَاعِ بَلْ يُنْمَى إِلَى الْمُسْتَنَدِ"],["وَمَنْعُ نَسْخِ النَّصِّ بِالْقِيَاسِ","هُوَ الَّذِي ارْتَضَاهُ جُلُّ النَّاسِ"],["وَنَسْخُ بَعْضِ الذِّكْرِ مُطْلَقًا وَرَدْ","وَالنَّسْخُ بِالنَّصِّ لِنَصٍّ مُعْتَمَدْ"],["وَالنَّسْخُ بِالْآحَادِ لِلْكِتَابِ","لَيْسَ بِوَاقِعٍ عَلَى الصَّوَابِ"],["وَيُنْسَخُ الْخِفُّ بِمَا لَهُ ثِقَلْ","وَقَدْ يَجِيءُ عَارِيًا مِنَ الْبَدَلْ"],["وَالنَّسْخُ مِنْ قَبْلِ وُقُوعِ الْفِعْلِ","جَاءَ وُقُوعًا فِي صَحِيحِ النَّقْلِ"],["وَجَازَ بِالْفَحْوَى وَنَسْخُهُ بِلَا","أَصْلٍ وَعَكْسُهُ جَوَازُهُ انْجَلَى"],["وَرَأْيُ الَاكْثَرِينَ الِاسْتِلْزَامُ","وَبِالْمُخَالَفَةِ لَا يُرَامُ"],["وَهْيَ عَنِ الْأَصْلِ لَهَا تَجَرُّدُ","فِي النَّسْخِ وَانْعِكَاسُهُ مُسْتَبْعَدُ"],["وَيَجِبُ الرَّفْعُ لِحُكْمِ الْفَرْعِ","إِنْ حُكْمُ أَصْلِهِ يُرَى ذَا رَفْعِ"],["وَيُنْسَخُ الْإِنْشَا وَلَوْ مُؤَبَّدَا","وَالْقَيْدُ فِي الْفِعْلِ أَوِ الْحُكْمِ بَدَا"],["وَفِي الْأَخِيرِ مَنَعَ ابْنُ الْحَاجِبِ","كَمُسْتَمِرٍّ بَعْدَ صَوْمٍ وَاجِبِ"],["وَنَسْخُ الِإخْبَارِ بِإِيجَابِ خَبَرْ","بِنَاقِضٍ يَجُوزُ لَا نَسْخُ الْخَبَرْ"],["وَكُلُّ حُكْمٍ قَابِلٌ لَهُ وَفِي","نَفْيِ الْوُقُوعِ الِاتِّفَاقُ قَدْ قُفِي"],["هَلْ يَسْتَقِلُّ الْحُكْمُ بِالْوُرُودِ","أَوْ بِبُلُوغِهِ إِلَى الْمَوْجُودِ"],["فَالْعَزْلُ بِالْمَوْتِ أَوِ الْعَزْلِ عَرَضْ","كَذَا قَضَاءُ جَاهِلٍ لِلْمُفْتَرَضْ"],["وَلَيْسَ نَسْخًا كُلُّ مَا أَفَادَا","فِيمَا رَسَا بِالنَّصِّ الِازْدِيَادَا"],["وَالنَّقْصُ لِلْجُزْءِ أَوِ الشَّرْطِ انْتُقِي","نَسْخُهُ لِلسَّاقِطِ لَا لِلَّذْ بَقِي"],["الِاجْمَاعُ وَالنَّصُّ عَلَى النَّسْخِ وَلَوْ","تَضَمُّنًا كُلًّا مُعَرِّفًا رَأَوْا"],["كَذَاكَ يُعْرَفُ لَدَى الْمُحَرِّرِ","بِالْمَنْعِ لِلْجَمْعِ مَعَ التَّأَخُّرِ"],["كَقَوْلِ رَاوٍ سَابِقٌ وَالْمَحْكِي","بِمَا يُضَاهِي الْمَدَنِي وَالْمَكَّي"],["وَقَوْلِهِ النَّاسِخُ وَالتَّأْثِيرَ دَعْ","بِوَفْقِ وَاحِدٍ لِلَاصْلِ يُتَّبَعْ"],["وَكَوْنِ رَاوِيهِ الصَّحَابِي يَقْتَفِي","وَمِثْلُهُ تَأَخُّرٌ فِي الْمُصْحَفِ"],["وَهْيَ مَا انْضَافَ إِلَى الرَّسُولِ","مِنْ صِفَةٍ كَلَيْسَ بِالطَّوِيلِ"],["وَالْقَوْلِ وَالْفِعْلِ وَفِي الْفِعْلِ انْحَصَرْ","تَقْرِيرُهُ كَذِي الْحَدِيثُ وَالْخَبَرْ"],["وَالْأَنْبِيَاءُ عُصِمُوا مِمَّا نُهُوا","عَنْهُ وَلَمْ يَكُنْ لَهُمْ تَفَكُّهُ"],["بِجَائِزٍ بَلْ ذَاكَ لِلتَّشْرِيعِ","أَوْ نِيَّةِ الزُّلْفَى مِنَ الرَّفِيعِ"],["فَالصَّمْتُ لِلنَّبِيِّ عَنْ فِعْلٍ عَلِمْ","بِهِ جَوَازُ الْفِعْلِ مِنْهُ قَدْ فُهِمْ"],["وَرُبَّمَا يَفْعَلُ لِلْمَكْرُوهِ","مُبَيِّنًا أَنَّهُ لِلتَّنْزِيهِ"],["فَصَارَ فِي جَانِبِهِ مِنَ الْقُرَبْ","كَالنَّهْيِ أَنْ يُشْرَبَ مِنْ فَمِ الْقِرَبْ"],["وَفِعْلُهُ الْمَرْكُوزُ فِي الْجِبِلَّهْ","كَالْأَكْلِ وَالشُّرْبِ فَلَيْسَ مِلَّهْ"],["مِنْ غَيْرِ لَمْحِ الْوَصْفِ وَالَّذِي احْتَمَلْ","شَرْعًا فَفِيهِ قُلْ تَرَدُّدٌ حَصَلْ"],["فَالْحَجُّ رَاكِبًا عَلَيْهِ يَجْرِي","كَضِجْعَةٍ بَعْدَ صَلَاةِ الْفَجْرِ"],["وَغَيْرُهُ وَحُكْمُهُ جَلِيُّ","فَالِاسْتِوَا فِيهِ هُوَ الْقَوِيُّ"],["مِنْ غَيْرِ تَخْصِيصٍ وَبِالنَّصِّ يُرَى","وَبِالْبَيَانِ وَامْتِثَالٍ ظَهَرَا"],["وَلِلْوُجُوبِ عَلَمُ النِّدَاءِ","كَذَاكَ قَدْ وُسِمَ بِالْقَضَاءِ"],["وَالتَّرْكُ إِنْ جَلَبَ لِلتَّعْزِيرِ","وَسْمٌ لِلِاسْتِقْرَا مِنَ الْبَصِيرِ"],["وَمَا تَمَحَّضَ لِقَصْدِ الْقُرْبِ","عَنْ قَيْدِ الِايجَابِ فَسِيْمَى النَّدْبِ"],["وَكُلُّ مَا الصِّفَةُ فِيهِ تُجْهَلُ","فَلِلْوُجُوبِ فِي الْأَصَحِّ يُجْعَلُ"],["وَقِيلَ مَعْ قَصْدِ التَّقَرُّبِ وَإِنْ","فُقِدَ فَهْوَ بِالْإِبَاحَةِ قَمِنْ"],["وَقَدْ رُوِي عَنْ مَالِكِ الْأَخِيرُ","وَالْوَقْفُ لِلْقَاضِي نَمَى الْبَصِيرُ"],["وَالنَّاسِخُ الْأَخِيرُ إِنْ تَقَابَلَا","فِعْلٌ وَقَوْلٌ مُتَكَرِّرًا جَلَا"],["وَالرَّأْيُ عِنْدَ جَهْلِهِ ذُو خُلْفِ","بَيْنَ مُرَجِّحٍ وَرَأْيِ الْوَقْفِ"],["وَالْقَوْلُ إِنْ خَصَّ بِنَا تَعَارَضَا","فِينَا فَقَطْ وَالنَّاسِخُ الَّذِي مَضَى"],["إِنْ بِالتَّأَسِّي أَذِنَ الدَّلِيلُ","وَالْجَهْلُ فِيهِ ذَلِكَ التَّفْصِيلُ"],["وَإِنْ يَعُمَّ غَيْرَهُ وَالِاقْتِدَا","بِهِ لَهُ نَصٌّ فَمَا قَبْلُ بَدَا"],["فِي حَقِّهِ الْقَوْلُ بِفِعْلٍ خُصَّا","إِنْ يَكُ فِيهِ الْقَوْلُ لَيْسَ نَصَّا"],["وَلَمْ يَكُنْ تَعَارُضُ الْأَفْعَالِ","فِي كُلِّ حَالَةٍ مِنَ الْأَحْوَالِ"],["وَإِنْ يَّكُ الْقَوْلُ بِحُكْمٍ لَامِعَا","فَآخِرُ الْفِعْلَيْنِ كَانَ رَافِعَا"],["وَالْكُلُّ عِنْدَ بَعْضِهِمْ صَحِيحُ","وَمَالِكٌ عَنْهُ رُوِي التَّرْجِيحُ"],["وَحَيْثُمَا قَدْ عُدِمَ الْمَصِيرُ","إِلَيْهِ فَالْأَوْلَى هُوَ التَّخْيِيرُ"],["وَلَمْ يَكُنْ مُكَلَّفًا بِشَرْعِ","صَلَّى عَلَيْهِ اللَّهُ قَبْلَ الْوَضْعِ"],["وَهْوَ وَالْأُمَّةُ بَعْدُ كُلِّفَا","إِلَّا إِذَا التَّكْلِيفُ بِالنَّصِّ انْتَفَى"],["وَقِيلَ لَا وَالْخُلْفُ فِيمَا شُرِعَا","وَلَمْ يَكُنْ دَاعٍ إِلَيْهِ سُمِعَا"],["وَمُفْهِمُ الْبَاطِلِ مِنْ كُلِّ خَبَرْ","فِي الْوَضْعِ أَوْ نَقْصٍ مِنَ الرَّاوِي انْحَصَرْ"],["وَالْوَضْعُ لِلنِّسْيَانِ وَالتَّرْهِيبِ","وَالْغَلَطِ التَّنْفِيْرِ وَالتَّرْغِيبِ"],["وَبَعْدَ أَنْ بُعِثَ خَيْرُ الْعَرَبِ","دَعْوَى النُّبُوَّةِ انْمِهَا لِلْكَذِبِ"],["وَمَا انْتَفَى وُجُودُهُ مِنْ نَصِّ","عِنْدَ ذَوِى الْحَدِيثِ بَعْدَ الْفَحْصِ"],["وَبَعْضَ مَا يُنْسَبُ لِلنَّبِيِّ","وَخَبَرَ الْآحَادِ فِي السَّنِيِّ"],["حَيْثُ دَوَاعِي نَقْلِهِ تَوَاتُرَا","نَرَى لَهَا لَوْ قَالَهُ تَقَرُّرَا"],["وَاقْطَعْ بِصِدْقِ خَبَرِ التَّوَاتُرِ","وَسَوِّ بَيْنَ مُسْلِمٍ وَكَافِرِ"],["وَاللَّفْظِ وَالْمَعْنَى وَذَاكَ خَبَرُ","مَنْ عَادَةً كِذِبُهُمْ مُنْحَظِرُ"],["عَنْ غَيْرِ مَعْقُولٍ وَأَوْجِبِ الْعَدَدْ","مِنْ غَيْرِ تَحْدِيدٍ عَلَى مَا يُعْتَمَدْ"],["وَقِيلَ بِالْعِشْرِينَ أَوْ بِأَكْثَرَا","أَوْ بِثَلَاثِينَ أَوِ اثْنَيْ عَشَرَا"],["إِلْغَاءُ الَارْبَعَةِ فِيهِ رَاجِحُ","وَمَا عَلَيْهَا زَادَ فَهْوَ صَالِحُ"],["وَأَوْجِبَنْ فِي طَبَقَاتِ السَّنَدِ","تَوَاتُرًا وَفْقًا لَدَى التَّعَدُّدِ"],["وَلَا يُفِيدُ الْقَطْعَ مَا يُوَافِقُ","الِاجْمَاعَ وَالْبَعْضُ بِقَطْعٍ يَنْطِقُ"],["وَبَعْضُهُمْ يُفِيدُ حَيْثُ عَوَّلَا","عَلَيْهِ وَانْفِهِ إِذَا مَا قَدْ خَلَا"],["مَعَ دَوَاعِي رَدِّهِ مِنْ مُبْطِلِ","كَمَا يَدُلُّ لِخِلَافَةِ عَلِي"],["كَالِافْتِرَاقِ بَيْنَ ذِي تَأَوُّلِ","وَعَامِلٍ بِهِ عَلَى الْمُعَوَّلِ"],["وَمَذْهَبُ الْجُمْهُورِ صِدْقُ مُخْبِرِ","مَعَ صَمْتِ جَمْعٍ لَمْ يَخَفْهُ حَاضِرِ"],["وَمُودَعٌ مِنَ النَّبِيِّ سَمْعَا","يُفِيدُ ظَنًّا أَوْ يُفِيدُ قَطْعَا"],["وَلَيْسَ حَامِلٌ عَلَى الْإِقْرَارِ","ثَمَّ مَعَ الصَّمْتِ عَنِ الْإِنْكَارِ"],["وَخَبَرُ الْآحَادِ مَظْنُونٌ عَرَى","عَنِ الْقُيُودِ فِي الَّذِي تَوَاتَرَا"],["وَالْمُسْتَفِيضُ مِنْهُ وَهْوَ أَرْبَعَهْ","أَقَلُّهُ وَبَعْضُهُمْ قَدْ رَفَعَهْ"],["عَنْ وَاحِدٍ وَبَعْضُهُمْ عَمَّا يَلِي","وَجَعْلُهُ وَاسِطَةً قَوْلٌ جَلِي"],["وَلَا يُفِيدُ الْعِلْمَ بِالْإِطْلَاقِ","عِنْدَ الْجَمَاهِيرِ مِنَ الْحُذَّاقِ"],["وَبَعْضُهُمْ يُفِيدُ إِنْ عَدْلٌ رَوَى","وَاخْتِيرَ ذَا إِنِ الْقَرِينَةَ احْتَوَى"],["وَفِي الشَّهَادَةِ وَفِي الْفَتْوَى الْعَمَلْ","بِهِ وُجُوبُهُ اتِّفَاقًا قَدْ حَصَلْ"],["كَذَاكَ جَاءَ فِي اتِّخَاذِ الْأَدْوِيَهْ","وَنَحْوِهَا كَسَفَرٍ وَالْأَغْذِيَّهْ"],["وَمَالِكٌ بِمَا سِوَى ذَاكَ نَخَعْ","وَمَا يُنَافِي نَقْلَ طَيْبَةَ مَنَعْ"],["إِذَّ ذَّاكَ قَطْعِيٌّ وَإِنْ رَأْيًا فَفِي","تَقْدِيمِ ذَا أَوْ ذَاكَ خُلْفٌ قَدْ قُفِي"],["كَذَاكَ فِيمَا عَارَضَ الْقِيَاسَا","رِوَايَتَا مَنْ أَحْكَمَ الْأَسَاسَا"],["وَقَدْ كَفَى مِنْ غَيْرِ مَا اعْتِضَادِ","خَبَرُ وَاحِدٍ مِنَ الْآحَادِ"],["وَالْجَزْمُ مِنْ فَرْعٍ وَشَكَّ الْأَصْلِ","وَدَعْ بِجَزْمِهِ لِذَاكَ النَّقْلِ"],["وَقَالَ بِالْقَبُولِ إِنْ لَمْ يَنْتَفِ","اصْلٌ مِنَ الْحَدِيثِ شَيْخٌ مُقْتَفِي"],["وَلَيْسَ ذَا يَقْدَحُ فِي الْعَدَالَهْ","كَشَاهِدٍ لِلْجَزْمِ بِالْمَقَالَهْ"],["وَالرَّفْعُ وَالْوَصْلُ وَزَيْدُ اللَّفْظِ","مَقْبُولَةٌ عِنْدَ إِمَامِ الْحِفْظِ"],["إِنْ أَمْكَنَ الذُّهُولُ عَنْهَا عَادَهْ","إِلَّا فَلَا قَبُولَ لِلزِّيَادَهْ"],["وَقِيلَ لَا إِنِ اتِّحَادٌ قَدْ عُلِمْ","وَالْوَفْقُ فِي غَيْرِ الَّذِي مَرَّ رُسِمْ"],["وَلِلتَّعَارُضِ نُمِي الْمُغَيِّرُ","وَحَذْفُ بَعْضٍ قَدْ رَآهُ الْأَكْثَرُ"],["دُونَ ارْتِبَاطٍ وَهْوَ فِي التَّأْلِيفِ","يَسُوغُ بِالْوَفْقِ بِلَا تَعْنِيفِ"],["بِغَالِبِ الظَّنِّ يَدُورُ الْمُعْتَبَرْ","فَاعْتَبَرَ الْإِسْلَامَ كُلُّ مَنْ غَبَرْ"],["وَفَاسِقٌ وَذُو ابْتِدَاعٍ إِنْ دَعَا","أَوْ مُطْلَقًا رَدٌّ لِكُلٍّ سُمِعَا"],["كَذَا الصَّبِي وَإِنْ يَكُنْ تَحَمَّلُوا","ثُمَّ أَدًا بِنَفْيِ مَنْعٍ قُبِلُوا"],["مَنْ لَيْسَ ذَا فِقْهٍ أَبَاهُ الْجِيلُ","وَعَكْسُهُ أَثْبَتَهُ الدَّلِيلُ"],["وَمَنْ لَهُ فِي غَيْرِهِ تَسَاهُلُ","ذُو عُجْمَةٍ أَوْ جَهْلِ مَنْمًى يُقْبَلُ"],["كَخُلْفِهِ لِأَكْثَرِ الرُّوَاةِ","وَخُلْفِهِ لِلْمُتَوَاتِرَاتِ"],["وَكَثْرَةٍ وَإِنُ لُقِيٌّ يَنْدُرُ","فِيمَا بِهِ تَحْصِيلُهُ لَا يُحْظَرُ"],["عَدْلُ الرِّوَايَةِ الَّذِي قَدْ أَوْجَبُوا","هُوَ الَّذِي مِنْ بَعْدِ هَذَا يُجْلَبُ"],["وَالْعَدْلُ مَنْ يَجْتَنِبُ الْكَبَائِرَا","وَيَتَّقِي فِي الْأَغْلَبِ الصَّغَائِرَا"],["وَمَا أُبِيحَ وَهْوَ فِي الْعِيَانِ","يَقْدَحُ فِي مُرُوءَةِ الْإِنْسَانِ"],["وَذُو أُنُوثَةٍ وَعَبْدٌ وَالْعِدَا","وَذُو قَرَابَةٍ خِلَافُ الشُّهَدَا"],["وَلَا صَغِيرَةَ مَعَ الْإِصْرَارِ","الْمُبْطِلِ الثِّقَةِ بِالْإِخْبَارِ"],["فَدَعْ لِمَنْ جُهِلَ مُطْلَقًا وَمَنْ","فِي عَيْنِهِ يُجْهَلُ أَوْ فِيمَا بَطَنْ"],["وَمُثْبِتُ الْعَدَالَةِ اخْتِبَارُ","كَذَاكَ تَعْدِيلٌ وَالِانْتِشَارُ"],["وَفِي قَضَا الْقَاضِي وَأَخْذِ الرَّاوِي","وَعَمَلِ الْعَالِمِ أَيْضًا ثَاوِي"],["وَشَرْطُ كُلٍّ أَنْ يُرَى مُلْتَزَمَا","رَدًّا لِمَنْ لَيْسَ بِعَدْلٍ عُلِمَا"],["وَالْجَرْحَ قَدِّمْ بِاتِّفَاقٍ أَبَدَا","إِنْ كَانَ مَنْ جَرَحَ أَعْلَى عَدَدَا"],["وَغَيْرُهُ كَهْوَ بِغَيْرِ مَيْنِ","وَقِيلَ بِالتَّرْجِيحِ فِي الْقِسْمَيْنِ"],["كِلَاهُمَا يُثْبِتُهُ الْمُنْفَرِدُ","وَمَالِكٌ عَنْهُ رُوِي التَّعَدُّدُ"],["وَقَالَ بِالْعَدَدِ ذُو دِرَايَهْ","فِي جِهَةِ الشَّاهِدِ لَا الرِّوَايَهْ"],["شَهَادَةٌ الْإِخْبَارُ عَمَّا خَصَّ إِنْ","فِيهِ تَرَافُعٌ إِلَى الْقَاضِي زُكِنْ"],["وَغَيْرُهُ رِوَايَةٌ وَالصَّحْبُ","تَعْدِيلُهُمْ كُلٌّ إِلَيْهِ يَصْبُو"],["وَاخْتَارَ فِي الْمُلَازِمِينَ دُونَ مَنْ","رَآهُ مَرَّةً إِمَامٌ مُؤْتَمَنْ"],["إِذَا ادَّعَى الْمُعَاصِرُ الْعَدْلُ الشَّرَفْ","بِصُحْبَةٍ يَقْبَلُهُ جُلُّ السَّلَفْ"],["وَمُرْسَلٌ قَوْلَةُ غَيْرِ مَنْ صَحِبْ","قَالَ إِمَامُ الْأَعْجَمِينَ وَالْعَرَبْ"],["عِنْدَ الْمُحَدِّثِينَ قَوْلُ التَّابِعِي","أَوِ الْكَبِيرِ قَالَ خَيْرُ شَافِعِ"],["وَهْوَ حُجَّةٌ وَلَكِنْ رُجِّحَا","عَلَيْهِ مُسْنَدٌ وَعَكْسٌ صُحِّحَا"],["وَالنَّقْلُ لِلْحَدِيثِ بِالْمَعْنَى مُنِعْ","وَمَالِكٌ عَنْهُ الْجَوَازُ قَدْ سُمِعْ"],["لِعَارِفٍ يَفْهَمُ مَعْنَاهُ جَزَمْ","وَغَالِبُ الظَّنِّ لَدَى الْبَعْضِ انْحَتَمْ"],["وَالِاسْتِوَاءُ فِي الْخَفَاءِ وَالْجَلَا","لَدَى الْمُجَوِّزِينَ حَتْمًا حَصَلَا"],["وَبَعْضُهُمْ مَنَعَ فِي الْقِصَارِ","دُونَ الَّتِي تَطُولُ لِاضْطِرَارِ"],["وَبِالْمُرَادِفِ يَجُوزُ قَطْعَا","وَبَعْضُهُمْ يَحْكُونَ فِيهِ الْمَنْعَا"],["وَجَوِّزَنْ وَفْقًا بِلَفْظٍ عَجَمِي","وَنَحْوِهِ الْإِبْدَالُ لِلْمُتَرْجِمِ"],["أَرْفَعُهَا الصَّرِيحُ فِي السَّمَاعِ","مِنَ الرَّسُولِ الْمُجْتَبَى الْمُطَاعِ"],["مِنْهُ سَمِعْتُ مِنْهُ ذَا أَوْ أَخْبَرَا","شَافَهَنِي حَدَّثَنِيهِ صَيَّرَا"],["فَقَالَ عَنْ ثُمَّ نُهِي أَوْ أُمِرَا","إِنْ لَمْ يَكُنْ خَيْرُ الْوَرَى قَدْ ذُكِرَا"],["كَذَا مِنَ السُّنَّةِ يُرْوَى وَالْتَحَقْ","كُنَّا بِهِ إِذَا بِعَهْدِهِ الْتَصَقْ"],["لِلْعَرْضِ وَالسَّمَاعِ وَالْإِذْنِ اسْتِوَا","مَتَى عَلَى النَّوَالِ ذَا الْإِذْنُ احْتَوَى"],["وَاعْمَلْ بِمَا عَنِ الْإِجَازَةِ رُوِي","إِنْ صَحَّ سَمْعُهُ بِظَنٍّ قَدْ قَوِي"],["لِشِبْهِهَا الْوَقْفَ تَجِي لِمَنْ عُدِمْ","وَعَدَمُ التَّفْصِيلِ فِيهِ مُنْحَتِمْ"],["وَالْكَتْبِ دُونَ الْإِذْنِ بِالَّذِي سُمِعْ","إِنْ عُرِفَ الْخَطُّ وَإِلَّا يَمْتَنِعْ"],["وَالْخُلْفُ فِي إِعْلَامِهِ الْمُجَرَّدِ","وَأَعْمِلَنْ مِنْهُ صَحِيحَ السَّنَدِ"],["وَالْأَخْذُ عَنْ وِجَادَةٍ مِمَّا انْحْظَلْ","وَفْقًا وَجُلُّ النَّاسِ يَمْنَعُ الْعَمَلْ"],["وَمَا بِهِ يُذْكَرُ لَفْظُ الْخَبَرِ","فَذَاكَ مَسْطُورٌ بِعِلْمِ الْأَثَرِ"],["وَهْوَ الِاتِّفَاقُ مِنْ مُجْتَهِدِي","الُامَّةِ مِنْ بَعْدِ وَفَاةِ أَحْمَدِ"],["وَأَطْلِقَنْ فِي الْعَصْرِ وَالْمُتَّفَقِ","عَلَيْهِ فَالْإِلْغَا لِمَنْ عَمَّ انْتُقِي"],["وَقِيلَ لَا وَقِيلَ فِي الْجَلِيِّ","مِثْلُ الزِّنَا وَالْحَجِّ لَا الْخَفِيِّ"],["وَقِيلَ لَا فِي كُلِّ مَا التَّكْلِيفُ","بِعِلْمِهِ قَدْ عَمَّمَ اللَّطِيفُ"],["وَذَا لِلِاحْتِجَاجِ أَوْ أَنْ يُطْلَقَا","عَلَيْهِ الِاجْمَاعُ وَكُلٌّ يُنْتَقَى"],["وَكُلُّ مَنْ بِبِدْعَةٍ يُكَفَّرُ","مِنْ أَهْلِ الَاهْوَاءِ فَلَا يُعْتَبَرُ"],["وَالْكُلُّ وَاجِبٌ وَقِيلَ لَا يَضُرّْ","الِاثْنَانِ دُونَ مَنْ عَلَيْهِمَا كَثُرْ"],["وَاعْتَبِرَنْ مَعَ الصَّحَابِي مَنْ تَبِعْ","إِنْ كَانَ مَوْجُودًا وَإِلَّا فَامْتَنِعْ"],["ثُمَّ انْقِرَاضُ الْعَصْرِ وَالتَّوَاتُرُ","لَغْوٌ عَلَى مَا يَنْتَحِيْهِ الَاكْثَرُ"],["وَهْوَ حُجَّةٌ وَلَكِنْ يُحْظَلُ","فِيمَا بِهِ كَالْعِلْمِ دَوْرٌ يَحْصُلُ"],["وَمَا إِلَى الْكُوفَةِ مِنْهُ يَنْتَمِي","وَالْخُلَفَاءِ الرَّاشِدِينَ فَاعْلَمِ"],["وَأَوْجِبَنْ حُجِّيَّةً لِلْمَدَنِي","فِيمَا عَلَى التَّوْقِيفِ أَمْرُهُ بُنَي"],["وَقِيلَ مُطْلَقًا وَمَا قَدْ أَجْمَعَا","عَلَيْهِ أَهْلُ الْبَيْتِ مِمَّا مُنِعَا"],["وَمَا عَرَا مِنْهُ عَلَى السَّنِيِّ","مِنَ الْأَمَارَةِ أَوِ الْقَطْعِيِّ"],["وَخَرْقُهُ فَامْنَعْ لِقَوْلٍ زَائِدِ","إِذْ لَمْ يَكُنْ ذَاكَ سِوَى مُعَانِدِ"],["وَقِيلَ إِنْ خَرَقَ وَالتَّفْصِيلُ","إِحْدَاثُهُ مَنَعَهُ الدَّلِيلُ"],["وَرِدَّةَ الْأُمَّةِ لَا الْجَهْلَ لِمَا","عَدَمُ تَكْلِيفٍ بِهِ قَدْ عُلِمَا"],["وَلَا يُعَارِضُ لَهُ دَلِيلُ","وَيُظْهَرُ الدَّلِيلُ وَالتَّأْوِيلُ"],["وَقَدِّمَنَّهُ عَلَى مَا خَالَفَا","إِنْ كَانَ بِالْقَطْعِ يُرَى مُتَّصِفَا"],["وَهْوَ الْمُشَاهَدُ أَوِ الْمَنْقُولُ","بِعَدَدِ التَّوَاتُرِ الْمَقُولُ"],["وَفِي انْقِسَامِهَا لِقِسْمَيْنِ وَكُلّْ","فِي قَوْلِهِ مُخْطٍ تَرَدُّدٌ نُقِلْ"],["وَجَعْلُ مَنْ سَكَتَ مِثْلَ مَنْ أَقَرّْ","فِيهِ خِلَافٌ بَيْنَهُمْ قَدِ اشْتَهَرْ"],["فَالِاحْتِجَاجُ بِالسُّكُوتِيِّ نَمَي","تَفْرِيعَهُ عَلَيْهِ مَنْ تَقَدَّمَا"],["وَهْوَ بِفَقْدِ السُّخْطِ وَالضِّدِّ حَرِى","مَعَ مُضِيِّ مُهْلَةٍ لِلنَّظَرِ"],["وَلَا يُكَفَّرُ الَّذِي قَدِ اتَّبَعْ","إِنْكَارَ الِاجْمَاعِ وَبِيسَ مَا ابْتَدَعْ"],["وَالْكَافِرُ الْجَاحِدُ مَا قَدْ أُجْمِعَا","عَلَيْهِ مِمَّا عِلْمُهُ قَدْ وَقَعَا"],["عَنِ الضَّرُورِيِّ مِنَ الدِّينِيِّ","وَمِثْلُهُ الْمَشْهُورُ فِي الْقَوِيِّ"],["إِنْ كَانَ مَنْصُوصًا وَفِي الْغَيْرِ اخْتَلَفْ","إِنْ قَدُمَ الْعَهْدُ بِالِاسْلَامِ السَّلَفْ"],["بِحَمْلِ مَعْلُومٍ عَلَى مَا قَدْ عُلِمْ","لِلِاسْتِوَا فِي عِلَّةِ الْحُكْمِ وُسِمْ"],["وَإِنْ تُرِدْ شُمُولَهُ لِمَا فَسَدْ","فَزِدْ لَدَى الْحَامِلِ وَالزَّيْدُ أَسَدّْ"],["وَالْحَامِلُ الْمُطْلَقُ وَالْمُقَيَّدُ","وَهْوَ قَبْلَ مَا رَوَاهُ الْوَاحِدُ"],["وَقَبْلَهُ الْقَطْعِيُّ مِنْ نَصٍّ وَمِنْ","إِجْمَاعِهِمْ عِنْدَ جَمِيعِ مَنْ فَطِنْ"],["وَمَا رُوِيَ مِنْ ذَمِّهِ فَقَدْ عُنِي","بِهِ الَّذِي عَلَى الْفَسَادِ قَدْ بُنِي"],["وَالْحَدُّ وَالْكَفَّارَةُ التَّقْدِيرُ","جَوَازُهُ فِيهَا هُوَ الْمَشْهُورُ"],["وَرُخْصَةٌ بِعَكْسِهَا وَالسَّبَبُ","وَغَيْرُهَا لِلِاتِّفَاقِ يُنْسَبُ"],["وَإِنْ نُمِي لِلْعُرْفِ مَا كَالطُّهْرِ","أَوِ الْمَحِيضِ فَهْوَ فِيهِ يَجْرِي"],["الَاصْلُ حُكْمُهُ وَمَا قَدْ شُبِّهَا","وَعِلَّةٌ رَابِعُهَا فَانْتَبِهَا"],["وَالْحُكْمُ أَوْ مَحَلُّهُ أَوْ مَا يَدُلّْ","تَأْصِيلُ كُلِّ وَاحِدٍ مِمَّا نُقِلْ"],["وَقِسْ عَلَيْهِ دُونَ شَرْطِ نَصِّ","يُجِيزُهُ بِالنَّوْعِ أَوْ بِالشَّخْصِ"],["وَعِلَّةٌ وُجُودُهَا الْوِفَاقُ","عَلَيْهِ يَأْبَى شَرْطَهُ الْحُذَّاقُ"],["وَحُكْمُ الَاصْلِ قَدْ يَكُونُ مُلْحَقَا","لِمَا مِنَ اعْتِبَارِ الَادْنَى حُقِّقَا"],["مُسْتَلْحِقُ الشَّرْعِ هُوَ الشَّرْعِيُّ","وَغَيْرُهُ لِغَيْرِهِ مَرْعِيُّ"],["وَمَا بِقَطْعٍ فِيهِ قَدْ تَعَبَّدَا","رَبِّي فَمُلْحَقٌ كَذَاكَ عُهِدَا"],["وَلَيْسَ حُكْمُ الَاصْلِ بِالْأَسَاسِ","مَتَى يَحِدْ عَنْ سَنَنِ الْقِيَاسِ"],["لِكَوْنِهِ مَعْنَاهُ لَيْسَ يُعْقَلُ","أَوِ التَّعَدِّيّ فِيهِ لَيْسَ يَحْصُلُ"],["وَحَيْثُمَا يَنْدَرِجُ الْحُكْمَانِ","فِي النَّصِّ فَالْأَمْرَانِ قُلْ سِيَّانِ"],["وَالْوَفْقُ فِي الْحُكْمِ لَدَى الْخَصْمَيْنِ","شَرْطُ جَوَازِ الْقَيْسِ دُونَ مَيْنِ"],["وَإِنْ يَكُنْ لِعِلَّتَيْنِ اخْتَلَفَا","تَرَكَّبَ الْأَصْلُ لَدَى مَنْ سَلَفَا"],["مُرَكَّبُ الْوَصْفِ إِذَا الْخَصْمُ مَنَعْ","وُجُودَ ذَا الْوَصْفِ فِي الَاصْلِ الْمُتَّبَعْ"],["وَرَدُّهُ انْتُقِي وَقِيلَ يُقْبَلُ","وَفِي التَّقَدُّمِ خِلَافٌ يُنْقَلُ"],["الْحُكْمُ فِي رَأْيٍ وَمَا تُشُبِّهَا","مِنَ الْمَحَلِّ عِنْدَ جُلِّ النُّبَهَا"],["وُجُودُ جَامِعٍ بِهِ مُتَمَّمَا","شَرْطٌ وَفِي الْقَطْعِ إِلَى الْقَطْعِ انْتَمَى"],["وَإِنْ تَكُنْ ظَنِّيَّةً فَالْأَدْوَنُ","لِذَا الْقِيَاسِ عَلَمٌ مُدَوَّنُ"],["وَالْفَرْعُ لِلْأَصْلِ بِبَاعِثٍ وَفِي","الْحُكْمِ نَوْعًا أَوْ بِجِنْسٍ يَقْتَفِي"],["وَمُقْتَضَى الضِّدِّ أَوِ النَّقِيضِ","لِلْحُكْمِ فِي الْفَرْعِ كَوَقْعِ الْبِيْضِ"],["بِعَكْسِ مَا خِلَافَ حُكْمٍ يَقْتَضِي","وَادْفَعْ بِتَرْجِيحٍ لِذَا الْمُعْتَرِضِ"],["وَعَدَمُ النَّصِّ وَالِاجْمَاعِ عَلَى","وِفَاقِهِ أَوْجَبَهُ مَنْ أَصَّلَا"],["مَنْعَ الدَّلِيلَيْنِ وَحُكْمُ الْفَرْعِ","ظُهُورُهُ قَبْلُ يُرَى ذَا مَنْعِ"],["مُعَرِّفُ الْحُكْمِ بِوَضْعِ الشَّارِعِ","وَالْحُكْمُ ثَابِتٌ بِهَا فَاتَّبِعِ"],["وَوَصْفُهَا بِالْبَعْثِ مَا اسْتُبِينَا","مِنْهُ سِوَى بَعْثِ الْمُكَلَّفِينَا"],["لِلدَّفْعِ وَالرَّفْعِ أَوِ الْأَمْرَيْنِ","وَاجِبَةُ الظُّهُورِ دُونَ مَيْنِ"],["وَمِنْ شُرُوطِ الْوَصْفِ الِانْضِبَاطُ","إِلَّا فَحِكْمَةٌ بِهَا يُنَاطُ"],["وَهْيَ الَّتِي مِنْ أَجْلِهَا الْوَصْفُ جَرَى","عِلَّةَ حُكْمٍ عِنْدَ كُلِّ مَنْ دَرَى"],["وَهْوَ لِلُّغَةِ وَالْحَقِيقَهْ","وَالشَّرْعِ وَالْعُرْفِ نَمَى الْخَلِيقَهْ"],["وَقَدْ يُعَلَّلُ بِمَا تَرَكَّبَا","وَامْنَعْ لِعِلَّةٍ بِمَا قَدْ أَذْهَبَا"],["وَالْخُلْفُ فِي التَّعْلِيلِ بِالَّذِي عُدِمْ","لِمَا ثُبُوتِيًّا كَنِسْبِيٍّ عُلِمْ"],["لَمْ تُلْفَ فِي الْمُعَلَّلَاتِ عِلَّهْ","خَالِيَةٌ مِنْ حِكْمَةٍ فِي الْجُمْلَهْ"],["وَرُبَّمَا يُعْوِزُنَا اطِّلَاعُ","لَكِنَّهُ لَيْسَ بِهِ امْتِنَاعُ"],["وَفِي ثُبُوتِ الْحُكْمِ عِنْدَ الِانْتِفَا","لِلظَّنِّ وَالنَّفْيِ خِلَافٌ عُرِفًا"],["وَعَلَّلُوا بِمَا خَلَتْ مِنْ تَعْدِيَّهْ","لِيُعْلَمَ امْتِنَاعُهُ وَالتَّقْوِيَهْ"],["مِنْهَا مَحَلُّ الْحُكْمِ أَوْ جُزْءٌ وَزِدْ","وَصْفًا إِذَا كُلٌّ لُزُومِيًّا يَرِدْ"],["وَجَازَ بِالْمُشْتَقِّ دُونَ اللَّقَبِ","وَإِنْ يَكُنْ مِنْ صِفَةٍ فَقَدْ أُبِي"],["وَعِلَّةٌ مَنْصُوصَةٌ تَعَدَّدُ","فِي ذَاتِ الِاسْتِنْبَاطِ خُلْفٌ يُعْهَدُ"],["وَذَاكَ فِي الْحُكْمِ الْكَثِيرُ اطْلَقَهْ","كَالْقَطْعِ مَعْ غُرْمِ نِصَابِ السَّرِقَهْ"],["وَقَدْ تُخَصِّصُ وَقَدْ تُعَمَّمُ","لِأَصْلِهَا لَكِنَّهَا لَا تَخْرِمُ"],["وَشَرْطُهَا التَّعْيِينُ وَالتَّقْدِيرُ","لَهَا جَوَازُهُ هُوَ التَّحْرِيرُ"],["وَمُقْتَضَى الْحُكْمِ وُجُودُهُ وَجَبْ","مَتَى يَكُنْ وُجُودُ مَانِعٍ سَبَبْ"],["كَذَا إِذَا انْتِفَاءَ شَرْطٍ كَانَا","وَفَخْرُهُمْ خِلَافُ ذَا أَبَانَا"],["وَمَسْلَكُ الْعِلَّةِ مَا دَلَّ عَلَى","عِلِّيَّةِ الشَّيْءِ مَتَى مَا حَصَلَا"],["الِاجْمَاعُ فَالنَّصُّ الصَّرِيحُ مِثْلُ","لِعِلَّةٍ فَسَبَبٍ فَيَتْلُو"],["مِنْ أَجْلِ ذَا فَنَحْوُ كَيْ إِذًاً فَمَا","ظَهَرَ لَامٌ ثَمَّتَ الْبَا عُلِمَا"],["فَالْفَاءُ لِلشَّارِعِ فَالْفَقِيهِ","فَغَيْرِهِ يُتْبَعُ بِالشَّبِيهِ"],["وَالثَّالِثُ الِايمَا اقْتِرَانُ الْوَصْفِ","بِالْحُكْمِ مَلْفُوظَيْنِ دُونَ خُلْفِ"],["وَذَلِكَ الْوَصْفُ أَوِ النَّظِيرُ","قِرَانُهُ لِغَيْرِهَا يَضِيرُ"],["كَمَا إِذَا سَمِعَ وَصْفًا فَحَكَمْ","وَذِكْرُهُ فِي الْحُكْمِ وَصْفًا قَدْ أَلَمّْ"],["إِنْ لَمْ يَكُنْ عِلَّتَهُ لَمْ يُفِدِ","وَمَنْعُهُ مِمَّا يُفِيتُ اسْتَفِدِ"],["تَرْتِيبَهُ الْحُكْمَ عَلَيْهِ وَاتَّضَحْ","تَفْرِيقُ حُكْمَيْنِ بِوَصْفِ الْمُصْطَلَحْ"],["أَوْ غَايَةٍ شَرْطٍ أَوِ اسْتِثْنَاءِ","تَنَاسُبُ الْوَصْفِ عَلَى الْبِنَاءِ"],["وَالسَّبْرِ وَالتَّقْسِيمُ قِسْمٌ رَابِعُ","أَنْ يَحْصُرَ الْأَوْصَافَ فِيهِ جَامِعُ"],["وَيُبْطِلَ الَّذِي لَهَا لَا يَصْلُحُ","فَمَا بَقِي تَعْيِينُهُ مُتَّضِحُ"],["مُعْتَرِضُ الْحَصْرِ فِي دَفْعِهِ يَرِدْ","بَحَثْتُ ثُمَّ بَعْدَ بَحْثِي لَمْ أَجِدْ"],["أَوِ انْفِقَادُ مَا سِوَاهَا الْأَصْلُ","وَلَيْسَ فِي الْحَصْرِ لِظَنٍّ حَظْلُ"],["وَهْوَ قَطْعِيٌّ إِذَا مَا نُمِيَا","لِلْقَطْعِ وَالظَّنِّي سِوَاهُ وُعِيَا"],["حُجِّيَّةُ الظَّنِّيِّ رَأْيُ الْأَكْثَرِ","فِي حَقِّ نَاظِرٍ وَفِي الْمُنَاظِرِ"],["إِنْ يُبْدِ وَصْفًا زَائِدًا مُعْتَرِضٌ","وَفَى بِهِ دُونَ الْبَيَانِ الْغَرَضُ"],["وَقَطْعُ ذِي السَّبْرِ إِذًا مُنْحَتِمُ","وَالْأَمْرُ فِي إِبْطَالِهِ مُنْبَهِمُ"],["أَبْطِلْ لِمَا طَرْدًا يُرَى وَيَبْطُلُ","غَيْرَ مُنَاسِبٍ لَهُ الْمُنْخَزِلُ"],["كَذَاكَ بِالْإِلْغَا وَإِنْ قَدْ نَاسَبَا","وَبِتَعَدِّي وَصْفِهِ الَّذِي اجْتَبَى"],["ثُمَّ الْمُنَاسَبَةُ وَالْإِخَالَهْ","مِنَ الْمَسَالِكِ بِلَا اسْتِحَالَهْ"],["ثُمَّ بِتَخْرِيجِ الْمَنَاطِ يَشْتَهِرْ","تَخْرِيجُهَا وَبَعْضُهُمْ لَا يَعْتَبِرْ"],["وَهْوَ أَنْ يُعَيِّنَ الْمُجْتَهِدُ","لِعِلَّةِ بِذِكْرِ مَا سَيَرِدُ"],["مِنَ التَّنَاسُبِ الَّذِي مَعْهُ اتَّضَحْ","تَقَارُنٌ وَالْأَمْرِ مِمَّا قَدْ قَدَحْ"],["وَوَاجِبٌ تَحْقِيقُ الِاسْتِقْلَالِ","بِنَفْيِ غَيْرِهِ مِنَ الْأَحْوَالِ"],["ثُمَّ الْمُنَاسِبُ الَّذِي تَضَمَّنَا","تَرَتُّبُ الْحُكْمِ عَلَيْهِ مَا اعْتَنَا"],["بِهِ الَّذِي شَرَعَ مِنْ إِبْعَادِ","مَفْسَدَةٍ أَوْ جَلْبِ ذِي سَدَادِ"],["وَيَحْصُلُ الْقَصْدُ بِشَرْعِ الْحُكْمِ","شَكًّا وَظَنًّا وَكَذَا بِالْجَزْمِ"],["وَقَدْ يَكُونُ النَّفْيُ فِيهِ أَرْجَحَا","كَآيِسٍ لِقَصْدِ نَسْلٍ نَكَحَا"],["بِالطَّرَفَيْنِ فِي الْأَصَحِّ عَلَّلُوا","فَقَصْرُ مُتْرَفٍ عَلَيْهِ يُنْقَلُ"],["ثُمَّ الْمُنَاسِبُ عَنَيْتُ الْحِكْمَهْ","مِنْهُ ضَرُورِيٌّ وَجَا تَتِمَّهْ"],["بَيْنَهُمَا مَا يَنْتَمِي لِلْحَاجِي","وَقَدِّمِ الْقَوِيَّ فِي الرَّوَاجِ"],["دِينٌ فَنَفْسٌ ثُمَّ عَقْلٌ نَسَبُ","مَالٌ إِلَى ضَرُورَةٍ تَنْتَسِبُ"],["وَرَتِّبَنْ وَلْتَعْطِفَنْ مُسَاوِيًا","عِرْضًا عَلَى الْمَالِ تَكُنْ مُوَافِيًا"],["فَحِفْظُهَا حَتْمٌ عَلَى الْإِنْسَانِ","فِي كُلِّ شِرْعَةٍ مِنَ الْأَدْيَانِ"],["أَلْحِقْ بِهِ مَا كَانَ ذَا تَكْمِيلِ","كَالْحَدِّ فِيمَا يُسْكِرُ الْقَلِيلِ"],["وَهْوَ حَلَالٌ فِي شَرَائِعِ الرُّسُلْ","غَيْرِ الَّذِي نَسَخَ شَرْعَهُ السُّبُلْ"],["أَبَاحَهَا فِي أَوَّلِ الْإِسْلَامِ","بَرَاءَةٌ لَيْسَتْ مِنَ الْأَحْكَامِ"],["وَالْبَيْعُ فَالْإِجَارَةُ الْحَاجِيُّ","خِيَارُ بَيْعٍ لَاحِقٌ جَلِيُّ"],["وَمَا يُتَمِّمُ لَدَى الْحُذَّاقِ","حَثٌّ عَلَى مَكَارِمِ الْأَخْلَاقِ"],["مِنْهُ مُوَافِقٌ أُصُولَ الْمَذْهَبِ","كَسَلْبِ الْأَعْبُدِ شَرِيفَ الْمَنْصِبِ"],["وَحُرْمَةِ الْقَذَرِ وَالْإِنْفَاقِ","عَلَى الْأَقَارِبِ ذَوِي الْإِمْلَاقِ"],["وَمَا يُعَارِضُ كِتَابَةٌ سَلَمْ","وَنَحْوُهُ وَأَكْلُ مَا صِيدَ يُؤَمّْ"],["مِنَ الْمُنَاسِبِ مُؤَثِّرٌ ذُكِرْ","بِالنَّصِّ وَالْإِجْمَاعِ نَوْعُهُ اعْتُبِرْ"],["فِي النَّوْعِ لِلْحُكْمِ وَإِنْ لَمْ يُعْتَبَرْ","بِذَيْنِ بَلْ تَرَتُّبُ الْحُكْمِ ظَهَرْ"],["عَلَى وِفَاقِهِ فَذَا الْمُلَائِمُ","أَقْوَاهُ مَا ذَكَرَ قَبْلُ الْقَاسِمُ"],["مِنَ اعْتِبَارِ النَّوْعِ فِي الْجِنْسِ وَمِنْ","عَكْسٍ وَمِنْ جِنْسٍ بِآخَرٍ زُكِنْ"],["أَخَصُّ حُكْمٍ مَنْعُ مِثْلِ الْخَمْرِ","أَوِ الْوُجُوبُ لِمُضَاهِي الْعَصْرِ"],["فَمُطْلَقُ الْحُكْمَيْنِ بَعْدَهُ الطَّلَبْ","وَهُوَ بِالتَّخْيِيرِ فِي الْوَضْعِ اصْطَحَبْ"],["فَكَوْنُهُ حُكْمًا كَمَا فِي الْوَصْفِ","مُنَاسِبٌ خَصَّصَهُ ذُو الْعُرْفِ"],["مَصْلَحَةٌ وَضِدُّهَا بَعْدُ فَمَا","كَوْنُ مَحَلِّهَا مِنَ الَّذْ عُلِمَا"],["فَقَدِّمِ الْأَخَصَّ وَالْغَرِيبُ","أَلْغَى اعْتِبَارَهُ الْعَلِي الرَّقِيبُ"],["وَالْوَصْفُ حَيْثُ الِاعْتِبَارُ يُجْهَلُ","فَهْوَ الِإسْتِصْلَاحُ قُلْ وَالْمُرْسَلُ"],["نَقْبَلُهُ لِعَمَلِ الصَّحَابَهْ","كَالنَّقْطِ لِلْمُصْحَفِ وَالْكِتَابَهْ"],["تَوْلِيَةِ الصِّدِّيقِ لِلْفَارُوقِ","وَهَدْمِ جَارِ مَسْجِدٍ لِلضِّيقِ"],["وَعَمَلِ السِّكَّةِ تَجْدِيدِ النِّدَا","وَالسِّجْنِ تَدْوِينُ الدَّوَاوِينِ بَدَا"],["اخْرِمْ مُنَاسِبًا بِمُفْسِدٍ لَزِمْ","لِلْحُكْمِ وَهْوَ غَيْرَ مَرْجُوحٍ عُلِمْ"],["وَالشَّبَهُ الْمُسْتَلْزَمُ الْمُنَاسِبَا","مِثْلُ الْوُضُو يَسْتَلْزِمُ التَّقَرُّبَا"],["مَعَ اعْتِبَارِ جِنْسِهِ الْقَرِيبِ","فِي مِثْلِهِ لِلْحُكْمِ لَا الْغَرِيبِ"],["صَلَاحُهُ لَمْ يُدْرَ دُونَ الشَّرْعِ","وَلَمْ يُنَطْ مُنَاسِبٌ بِالسَّمْعِ"],["وَحَيْثُمَا أَمْكَنَ قَيْسُ الْعِلَّةِ","فَتَرْكَهُ بِالِاتِّفَاقِ أَثْبِتِ"],["إِلَّا فَفِي قَبُولِهِ تَرَدُّدُ","غَلَبَةُ الْأَشْبَاهِ هُوَّ الْأَجْوَدُ"],["فِي الْحُكْمِ وَالصِّفَةِ ثُمَّ الْحُكْمِ","فَصِفَةٍ فَقَطْ لَدَى ذِي الْعِلْمِ"],["وَابْنُ عُلَيَّةَ يَرَى لِلصُّورِي","كَالْقَيْسِ لِلْخَيْلِ عَلَى الْحَمِيرِ"],["أَنْ يُوجَدَ الْحُكْمُ لَدَى وُجُودِ","وَصْفٍ وَيَنْتَفِي لَدَى الْفُقُودِ"],["وَالْوَصْفُ ذُو تَنَاسُبٍ أَوِ احْتَمَلْ","لَهُ وَإِلَّا فَعَنِ الْقَصْدِ اعْتَزَلْ"],["وَهْوَ عِنْدَ الْأَكْثَرِينَ سَنَدُ","فِي صُورَةٍ أَوْ صُورَتَيْنِ يُوجَدُ"],["أَصْلٌ كَبِيرٌ فِي أُمُورِ الْآخِرَهْ","وَالنَّافِعَاتِ عَاجِلًا وَالضَّائِرَهْ"],["وُجُودُ حُكْمٍ حَيْثُمَا الْوَصْفُ حَصَلْ","وَالِاقْتِرَانُ فِي انْتِفَا الْوَصْفِ انْحَظَلْ"],["وَلَمْ يَكُنْ تَنَاسُبٌ بِالذَّاتِ","أَوْ تَبَعٍ فِيهِ لَدَى الثِّقَاتِ"],["وَرَدَّهُ النَّقْلُ عَنِ الصَّحَابَهْ","وَمَنْ رَأَى بِالْأَصْلِ قَدْ أَجَابَهْ"],["وَالْعَكْسُ وَهْوَ الدَّوَرَانُ الْعَدَمِي","لَيْسَ بِمَسْلَكٍ لِتِلْكَ فَاعْلَمِ"],["أَنْ يَنْتَفِي الْحُكْمُ مَتَى الْوَصْفُ انْتَفَى","وَمَا لَدَى الْوُجُودِ إِثْرَهُ اقْتَفَا"],["وَهُوَ أَنْ يَجِي عَلَى التَّعْلِيلِ","بِالْوَصْفِ ظَاهِرٌ مِنَ التَّنْزِيلِ"],["أَوِ الْحَدِيثِ فَالْخُصُوصَ يَطْرُدُ","عَنِ اعْتِبَارِ الشَّارِعِ الْمُجْتَهِدُ"],["فَمِنْهُ مَا كَانَ بِإِلْغَا الْفَارِقِ","وَمَا بِغَيْرٍ مِنْ دَلِيلٍ رَائِقِ"],["مِنَ الْمَنَاطِ أَنْ تَجِي أَوْصَافُ","فَبَعْضُهَا يَأْتِي لَهُ انْحِذَافُ"],["عَنِ اعْتِبَارِهِ وَمَا قَدْ بَقِيَا","تَرَتُّبُ الْحُكْمِ عَلَيْهِ اقْتُفِيَا"],["تَحْقِيقُ عِلَّةٍ عَلَيْهَا ائْتُلِفَا","فِي الْفَرْعِ تَحْقِيقُ مَنَاطٍ أُلِفَا"],["وَالْعَجْزُ عَنْ إِبْطَالِ وَصْفٍ لَمْ يُفِدْ","عِلِّيَّةً لَهُ عَلَى الَّذِي اعْتُمِدْ"],["كَذَا إِذَا مَا أَمْكَنَ الْقِيَاسُ","بِهِ عَلَى الَّذِي ارْتَضَاهُ النَّاسُ"],["مِنْهَا وُجُودُ الْوَصْفِ دُونَ الْحُكْمِ","سَمَّاهُ بِالنَّقْضِ وُعَاةُ الْعِلْمِ"],["وَالْأَكْثَرُونَ عِنْدَهُمْ لَا يَقْدَحُ","بَلْ هُوَ تَخْصِيصٌ وَذَا مُصَحَّحُ"],["وَقَدْ رُوِى عَنْ مَالِكٍ تَخْصِيصُ","إِنْ يَكُ الِاسْتِنْبَاطُ لَا التَّنْصِيصُ"],["وَعَكْسُ هَذَا قَدْ رَآهُ الْبَعْضُ","وَمُنْتَقَى ذِي الِاخْتِصَارِ النَّقْضُ"],["إِنْ لَمْ تَكُنْ مَنْصُوصَةً بِظَاهِرِ","وَلَيْسَ فِيمَا اسْتُنْبِطَتْ بِضَائِرِ"],["إِنْ جَا لِفَقْدِ الشَّرْطِ أَوْ لِمَا مَنَعْ","وَالْوَفْقُ فِي مِثْلِ الْعَرَايَا قَدْ وَقَعْ"],["جَوَابُهُ مَنْعُ وُجُودِ الْوَصْفِ أَوْ","مَنْعُ انْتِفَاءِ الْحُكْمِ فِيمَا قَدْ رَوَوْا"],["وَالْكَسْرُ قَادِحٌ وَمِنْهُ ذَكَرَا","تَخَلُّفَ الْحِكْمَةِ عَنْهُ مَنْ دَرَى"],["وَمِنْهُ إِبْطَالٌ لِجُزْءٍ وَالْحِيَلْ","ضَاقَتْ عَلَيْهِ فِي الْمَجِيئِ بِالْبَدَلْ"],["وَعَدَمُ الْعَكْسِ مَعَ اتِّحَادِ","يَقْدَحُ دُونَ النَّصِّ بِالتَّمَادِي"],["وَالْوَصْفُ إِنْ يُعْدَمْ لَهُ تَأْثِيرُ","فَذَاكَ لِانْتِقَاضِهِ يَصِيرُ"],["خُصَّ بِذِي الْعِلَّةِ بِائْتِلَافِ","وَذَاتِ الِاسْتِنْبَاطِ وَالْخِلَافِ"],["يَجِيءُ فِي الطَّرْدِيِّ حَيْثُ عُلِّلَا","بِهِ وَقَدْ يَجِيءُ فِيمَا أُصِّلَا"],["وَذَا بِإِبْدَا عِلَّةٍ لِلْحُكْمِ","مِمَّنْ يَرَى تَعَدُّدًا ذَا سُقْمِ"],["وَقَدْ يَجِي فِي الْحُكْمِ وَهْوَ أَضْرُبُ","فَمِنْهُ مَا لَيْسَ لِفَيْدٍ يُجْلَبُ"],["وَمَا لِفَيْدٍ عَنْ ضَرُورَةٍ ذُكِرْ","أَوْ لَا وَفِي الْعَفْوِ خِلَافٌ قَدْ سُطِرْ"],["وَالْقَلْبُ إِثْبَاتُ الَّذِي الْحُكْمَ نَقَضْ","بِالْوَصْفِ وَالْقَدْحُ بِهِ لَا يُعْتَرَضْ"],["فَمِنْهُ مَا صَحَّحَ رَأْيَ الْمُعْتَرِضْ","مَعْ أَنَّ رَأْيَ الْخَصْمِ فِيهِ مُنْتَقِضْ"],["وَمِنْهُ مَا يُبْطِلُ بِالْتِزَامِ","أَوِ الطِّبَاقِ رَأْيَ ذِي الْخِصَامِ"],["وَمِنْهُ مَا إِلَى الْمُسَاوَاةِ نُسِبْ","ثُبُوتُ حُكْمَيْنِ لِلْأَصْلِ يَنْسَلِبْ"],["حُكْمٌ عَنِ الْفَرْعِ بِالِائْتِلَافِ","وَوَاحِدٌ مِنْ ذَيْنِ ذُو اخْتِلَافِ"],["فَيُلْحَقُ الْفَرْعُ بِالْأَصْلِ فَيَرِدْ","كَوْنُ التَّسَاوِي وَاجِبًا مِنْ مُنْتَقِدْ"],["قَبُولُهُ فِيهِ خِلَافًا يَحْكِي","بَعْضُ شُرُوحِ الْجَمْعِ لِابْنِ السُّبْكِي"],["وَالْقَوْلُ بِالْمُوجَبِ قَدْحُهُ جَلَا","وَهُوَ تَسْلِيمُ الدَّلِيلِ مُسْجَلَا"],["مِنْ مَانِعٍ أَنَّ الدَّلِيلَ اسْتَلْزَمَا","لِمَا مِنَ الصُّوَرِ فِيهِ اخْتُصِمَا"],["يَجِيئُ فِي النَّفْيِ وَفِي الثُّبُوتِ","وَلِشُمُولِ اللَّفْظِ وَالسُّكُوتِ"],["عَمَّا مِنَ الْمُقَدِّمَاتِ قَدْ خَلَا","مِنْ شُهْرَةٍ لِخَوْفِهِ أَنْ تُحْظَلَا"],["وَالْفَرْقُ بَيْنَ الْفَرْعِ وَالْأَصْلِ قَدَحْ","إِبْدَاءُ مُخْتَصٍّ بِالْأَصْلِ قَدْ صَلَحْ"],["أَوْ مَانِعٍ فِي الْفَرْعِ وَالْجَمْعَ يَرَى","إِلَّا فَلَا فَرْقَ أُنَاسٌ كُبَرَا"],["تَعَدُّدُ الْأَصْلِ لِفَرْعٍ مُعْتَمَدْ","إِذْ يُوجِبُ الْقُوَّةَ تَكْثِيرُ السَّنَدْ"],["فَالْفَرْقُ بَيْنَهُ وَأَصْلٍ قَدْ كَفَى","وَقَالَ لَا يَكْفِيهِ بَعْضُ الْعُرَفَا"],["وَقِيلَ إِنْ أُلْحِقَ بِالْمَجْمُوعِ","فَوَاحِدٌ يَكْفِيهِ لَا الْجَمِيعِ"],["وَهَلْ إِذَا اشْتَغَلَ بِالتِّبْيَانِ","يَكْفِي جَوَابُ وَاحِدٍ قَوْلَانِ"],["مِنَ الْقَوَادِحِ فَسَادُ الْوَضْعِ أَنْ","يَجِي الدَّلِيلُ حَائِدًا عَنِ السَّنَنْ"],["كَالْأَخْذِ لِلتَّوْسِيعِ وَالتَّسْهِيلِ","وَالنَّفْيِ وَالْإِثْبَاتِ مِنْ عَدِيلِ"],["مِنْهُ اعْتِبَارُ الْوَصْفِ بِالْإِجْمَاعِ","وَالذِّكْرِ أَوْ حَدِيثِهِ الْمُطَاعِ"],["بِنَاقِضِ الْحُكْمِ بِذَا الْقِيَاسِ","جَوَابُهُ بِصِحَّةِ الْأَسَاسِ"],["وَالْخُلْفَ لِلنَّصِّ أَوْ إِجْمَاعٍ دَعَا","فَسَادَ الِاعْتِبَارِ كُلُّ مَنْ وَعَى"],["وَذَاكَ مِنْ هَذَا أَخَصُّ مُطْلَقَا","وَكَوْنُهُ ذَا الْوَجْهِ مِمَّا يُنْتَقَى"],["وَجَمْعُهُ بِالْمَنْعِ لَا يَضِيرُ","كَانَ لَهُ التَّقْدِيمُ وَالتَّأْخِيرُ"],["مِنَ الْقَوَادِحِ كَمَا فِي النَّقْلِ","مَنْعُ وُجُودِ عِلَّةٍ لِلْأَصْلِ"],["وَمَنْعُ عِلِّيَّةِ مَا يُعَلَّلُ","بِهِ وَقَدْحُهُ هُوَ الْمُعَوَّلُ"],["وَيَقْدَحُ التَّقْسِيمُ أَنْ يَحْتَمِلَا","لَفْظٌ لِأَمْرَيْنِ وَلَكِنْ حُظِلَا"],["وُجُودُ عِلَّةٍ بِأَمْرٍ وَاحِدِ","وَلَيْسَ عِنْدَ بَعْضِهِمْ بِالْوَارِدِ"],["جَوَابُهُ بِالْوَضْعِ فِي الْمُرَادِ","أَوِ الظُّهُورِ فِيهِ بِاسْتِشْهَادِ"],["وَلِلْمُعَارَضَةِ وَالْمَنْعِ مَعَا","أَوِ الْأَخِيرِ الِاعْتِرَاضُ رَجَعَا"],["وَالِاعْتِرَاضُ يَلْحَقُ الدَّلِيلَا","دُونَ الْحِكَايَةِ فَلَا سَبِيلَا"],["وَالشَّأْنُ لَا يُعْتَرَضُ الْمِثَالُ","إِذْ قَدْ كَفَى الْفَرْضُ وَالِاحْتِمَالُ"],["وَهُوَ مَفْرُوضٌ إِذَا لَمْ يَكُنِ","لِلْحُكْمِ مِنْ نَصٍّ عَلَيْهِ يَنْبَنِي"],["لَا يَنْتَمِي لِلْغَوْثِ وَالْجَلِيلِ","إِلَّا عَلَى ضَرْبٍ مِنَ التَّأْوِيلِ"],["وَهُوَ مَعْدُودٌ مِنَ الْأُصُولِ","وَشِرْعَةِ الْإِلَهِ وَالرَّسُولِ"],["مَا فِيهِ نَفْيُ فَارِقٍ وَلَوْ بِظَنْ","جَلِي وَبِالْخَفِيِّ عَكْسَهُ اسْتَبِنْ"],["كَوْنُ الْخَفِيِّ بِالشَّبْهِ دَأْبًا يَسْتَوِي","وَبَيْنَ ذَيْنِ وَاضِحٌ مِمَّا رُوِي"],["قِيلَ الْجَلِي وَوَاضِحٌ وَذُو الْخَفَا","أَوْلَى مُسَاوٍ أَدْوَنٌ قَدْ عُرِفَا"],["وَمَا بِذَاتِ عِلَّةٍ قَدْ جُمِعَا","فِيهِ فَقَيْسُ عِلَّةٍ قَدْ سُمِعَا"],["جَامِعُ ذِي الدَّلَالَةِ الَّذِي لَزِمْ","فَأَثَرٌ فَحُكْمُهَا كَمَا رُسِمْ"],["قِيَاسَ مَعْنَى الْأَصْلِ عَنْهُمْ حَقِّقِ","لِمَا دُعِي الْجَمْعَ بِنَفْيِ الْفَارِقِ"],["مَا لَيْسَ بِالنَّصِّ مِنَ الدَّلِيلِ","وَلَيْسَ بِالْإِجْمَاعِ وَالتَّمْثِيلِ"],["مِنْهُ قِيَاسُ الْمَنْطِقِي وَالْعَكْسِ","وَمِنْهُ فَقْدُ الشَّرْطِ دُونَ لَبْسِ"],["ثُمَّ انْتِفَا الْمُدْرَكِ مِمَّا يُرْتَضَى","كَذَا وُجُودُ مَانِعٍ أَوْ مَا اقْتَضَى"],["وَمِنْهُ الِاسْتِقْرَاءُ بِالْجُزْئِيِّ","عَلَى ثُبُوتِ الْحُكْمِ لِلْكُلِّيِّ"],["فَإِنْ يَعُمَّ غَيْرَ ذِي الشِّقَاقِ","فَهُوَ حُجَّةٌ بِالِاتِّفَاقِ"],["وَهُوَ فِي الْبَعْضِ إِلَى الظَّنِّ انْتَسَبْ","يُسْمَى لُحُوقَ الْفَرْدِ بِالَّذِي غَلَبْ"],["وَرَجِّحَنَّ كَوْنَ الِاسْتِصْحَابِ","لِلْعَدَمِ الْأَصْلِيِّ مِنْ ذَا الْبَابِ"],["بَعْدَ قُصَارَى الْبَحْثِ عَنْ نَصٍّ فَلَمْ","يُلْفَ وَهَذَا الْبَحْثُ وَفْقًا مُنْحَتِمْ"],["وَإِنْ يُعَارِضْ غَالِبًا ذَا الْأَصْلُ","فَفِي الْمُقَدَّمِ تَنَافِي النَّقْلُ"],["وَمَا عَلَى ثُبُوتِهِ لِلسَّبَبِ","شَرْعٌ يَدُلُّ مِثْلَ ذَاكَ اسْتَصْحِبِ"],["وَمَا بِمَاضٍ مُثْبَتٌ لِلْحَالِ","فَهُوَ مَقْلُوبٌ وَعَكْسُ الْخَالِي"],["كَجَرْيِ مَا جُهِلَ فِيهِ الْمَصْرِفُ","عَلَى الَّذِي الْآنَ لِذَاكَ يُعْرَفُ"],["وَالْأَخْذُ بِالَّذِي لَهُ رُجْحَانُ","مِنَ الْأَدِلَّةِ هُوَ اسْتِحْسَانُ"],["أَوْ هُوَ تَخْصِيصٌ بِعُرْفٍ مَا يَعُمْ","وَرَعْيَ الِاسْتِصْلَاحِ بَعْضُهُمْ يَؤُمْ"],["وَرَدُّ كَوْنِهِ دَلِيلًا يَنْقَدِحْ","وَيَقْصُرُ التَّعْبِيرُ عَنْهُ مُتَّضِحْ"],["رَأْيُ الصَّحَابِيِّ عَلَى الْأَصْحَابِ لَا","يَكُونُ حُجَّةً بِوَفْقِ مَنْ خَلَا"],["فِي غَيْرِهِ ثَالِثُهَا إِنِ انْتَشَرْ","وَمَا مُخَالِفٌ لَهُ قَطُّ ظَهَرْ"],["وَيَقْتَدِي مَنْ عَمَّ بِالْمُجْتَهِدِ","مِنْهُمْ لَدَى تَحَقُّقِ الْمُعْتَمَدِ"],["وَالتَّابِعِي فِي الرَّأْيِ لَا يُقَلِّدُ","لَهُ مِنْ أَهْلِ الِاجْتِهَادِ أَحَدُ"],["مَنْ لَمْ يَكُنْ مُجْتَهِدًا فَالْعَمَلُ","مِنْهُ بِمَعْنَى النَّصِّ مِمَّا يُحْظَلُ"],["سَدُّ الذَّرَائِعِ إِلَى الْمُحَرَّمِ","حَتْمٌ كَفَتْحِهَا إِلَى الْمُنْحَتِمِ"],["وَبِالْكَرَاهَةِ وَنَدْبٍ وَرَدَا","وَأَلْغِ إِنْ يَكُ الْفَسَادُ أَبْعَدَا"],["أَوْ رَجَحَ الْإِصْلَاحُ كَالْأُسَارَى","تُفْدَى بِمَا يَنْفَعُ لِلنَّصَارَى"],["وَانْظُرْ تَدَلِّيَ دَوَالِي الْعِنَبِ","فِي كُلِّ مَشْرِقٍ وَكُلِّ مَغْرِبِ"],["وَيُنْبَذُ الْإِلْهَامُ بِالْعَرَاءِ","أَعْنِي بِهِ إِلْهَامَ الْأَوْلِيَاءِ"],["وَقَدْ رَآهُ بَعْضُ مَنْ تَصَوَّفَا","وَعِصْمَةُ النَّبِيِّ تُوجِبُ اقْتِفَا"],["لَا يَحْكُمُ الْوَلِي بِلَا دَلِيلِ","مِنَ النُّصُوصِ أَوْ مِنَ التَّأْوِيلِ"],["فِي غَيْرِهِ الظَّنُّ وَفِيهِ الْقَطْعُ","لِأَجْلِ كَشْفٍ مَا عَلَيْهِ نَقْعُ"],["وَالظَّنُّ يَخْتَصُّ بِخَمْسِ الْغَيْبِ","لِنَفْيِ عِلْمِهَا بِدُونِ رَيْبِ"],["قَدْ أُسِّسَ الْفِقْهُ عَلَى رَفْعِ الضَّرَرْ","وَأَنَّ مَا يَشُقُّ يَجْلِبُ الْوَطَرْ"],["وَنَفْيِ رَفْعِ الْقَطْعِ بِالشَّكِّ وَأَنْ","يُحَكَّمَ الْعُرْفُ وَزَادَ مَنْ فَطَنْ"],["كَوْنَ الْأُمُورِ تَبَعَ الْمَقَاصِدِ","مَعَ تَكَلُّفٍ بِبَعْضِ وَارِدِ"],["وَلَا يَجِي تَعَارُضٌ إِلَّا لِمَا","مِنَ الدَّلِيلَيْنِ إِلَى الظَّنِّ انْتَمَى"],["وَالِاعْتِدَالُ جَائِزٌ فِي الْوَاقِعِ","كَمَا يَجُوزُ عِنْدَ ذِهْنِ السَّامِعِ"],["وَقَوْلُ مَنْ عَنْهُ رُوِي قَوْلَانِ","مُؤَخَّرٌ إِذْ يَتَعَاقَبَانِ"],["إِلَّا فَمَا صَاحَبَهُ مُؤَيِّدُ","وَغَيْرُهُ فِيهِ لَهُ تَرَدُّدُ"],["وَذِكْرُ مَا ضُعِّفَ لَيْسَ لِلْعَمَلْ","إِذْ ذَّاكَ عَنْ وِفَاقِهِمْ قَدِ انْحَظَلْ"],["بَلْ لِلتَّرَقِّي لِمَدَارِجِ السَّنَا","وَيَحْفَظَ الْمُدْرَكَ مَنْ لَهُ اعْتِنَا"],["وَلِمُرَاعَاةِ الْخِلَافِ الْمُشْتَهِرْ","أَوِ الْمُرَاعَاةِ لِكُلِّ مَا سُطِرْ"],["وَكَوْنِهِ يُلْجِي إِلَيْهِ الضَّرَرُ","إِنْ كَانَ لَمْ يَشْتَدَّ فِيهِ الْخَوَرُ"],["وَثَبَتَ الْعَزْوُ وَقَدْ تَحَقَّقَا","ضُرًّا مَنِ الضُّرُّ بِهِ تَعَلَّقَا"],["فَقَوْلُ مَنْ قَلَّدَ عَالِمًا لَقِي","اللَّهَ سَالِمًا فَغَيْرُ مُطْلَقِ"],["إِنْ لَمْ يَكُنْ لِنَحْوِ مَالِكٍ أُلِفْ","قَوْلٌ بِذِي وَفِي نَظِيرِهَا عُرِفْ"],["فَذَاكَ قَوْلُهُ بِهَا الْمُخَرَّجُ","وَقِيلَ عَزْوُهُ إِلَيْهِ حَرَجُ"],["وَفِي انْتِسَابِهِ إِلَيْهِ مُطْلَقًا","خُلْفٌ مَضَى إِلَيْهِ مَنْ قَدْ سَبَقَا"],["وَتَنْشَأُ الطُّرُقُ مِنْ نَصَّيْنِ","تَعَارَضَا فِي مُتَشَابِهَيْنِ"],["تَقْوِيَةُ الشِّقِّ هِيَ التَّرْجِيحُ","وَأَوْجَبَ الْأَخْذَ بِهِ الصَّحِيحُ"],["وَعَمَلٌ بِهِ أَبَاهُ الْقَاضِي","إِذَا بِهِ الظَّنُّ يَكُونُ الْقَاضِي"],["وَالْجَمْعُ وَاجِبٌ مَتَى مَا أَمْكَنَا","إِلَّا فَلِلْأَخِيرِ نَسْخٌ بُيِّنَا"],["وَوَجَبَ الْإِسْقَاطُ بِالْجَهْلِ وَإِنْ","تَقَارَنَا فَفِيهِ تَخْيِيرٌ زُكِنْ"],["وَحَيْثُمَا ظُنَّ الدَّلِيلَانِ مَعَا","فَفِيهِ تَخْيِيرٌ لِقَوْمٍ سُمِعَا"],["أَوْ يَجِبُ الْوَقْفُ أَوِ التَّسَاقُطُ","وَفِيهِ تَفْصِيلٌ حَكَاهُ الضَّابِطُ"],["وَإِنْ يُقَدَّمْ مُشْعِرٌ بِالظَّنِّ","فَانْسَخْ بِآخِرٍ لَدَى ذِي الْفَنِّ"],["ذُو الْقَطْعِ فِي الْجَهْلِ لَدَيْهِمْ مُعْتَبَرْ","وَإِنْ يَعُمَّ وَاحِدٌ فَقَدْ غَبَرْ"],["قَدْ جَاءَ فِي الْمُرَجِّحَاتِ بِالسَّنَدْ","عُلُوُّهُ وَالزَّيْدُ فِي الْحِفْظِ يُعَدْ"],["وَالْفِقْهُ وَاللُّغَةُ وَالنَّحْوُ وَرَعْ","وَضَبْطُهُ وَفِطْنَةٌ فَقْدُ الْبِدَعْ"],["عَدَالَةٌ بِقَيْدِ الِاشْتِهَارِ","وَكَوْنُهُ زُكِّي بِاخْتِبَارِ"],["صَرِيحُهَا وَأَنْ يُزَكِّي الْأَكْثَرُ","وَفَقْدُ تَدْلِيسٍ كَمَا قَدْ ذَكَرُوا"],["حُرِّيَّةٌ وَالْحِفْظُ عِلْمُ النَّسَبِ","وَكَوْنُهُ أَقْرَبَ أَصْحَابِ النَّبِي"],["ذُكُورَةٌ إِنْ حَالُهُ قَدْ جُهِلَا","وَقِيلَ لَا وَبَعْضُهُمْ قَدْ فَصَّلَا"],["مَا كَانَ أَظْهَرَ رِوَايَةً وَمَا","وَجْهُ التَّحَمُّلِ بِهِ قَدْ عُلِمَا"],["تَأَخُّرُ الْإِسْلَامِ وَالْبَعْضُ اعْتَمَى","تَرْجِيحَ مَنْ إِسْلَامُهُ تَقَدَّمَا"],["وَكَوْنُهُ مُبَاشِرًا أَوْ كُلِّفَا","أَوْ غَيْرَ ذِي اسْمَيْنِ لِلَامْنِ مِنْ خَفَا"],["أَوْ رَاوِيًا بِاللَّفْظِ أَوْ ذَا الْوَاقِعِ","وَكَوْنُ مَنْ رَوَّاهُ غَيْرَ مَانِعِ"],["وَكَوْنُهُ أُودِعَ فِي الصَّحِيحِ","لِمُسْلِمٍ وَالشَّيْخِ ذِي التَّرْجِيحِ"],["وَكَثْرَةُ الدَّلِيلِ وَالرِّوَايَهْ","مُرَجِّحٌ لَدَى ذَوِي الدِّرَايَهْ"],["وَقَوْلُهُ فَالْفِعْلُ فَالتَّقْرِيرُ","فَصَاحَةٌ وَأُلْغِيَ الْكَثِيرُ"],["زِيَادَةٌ وَلُغَةُ الْقَبِيلِ","وَرُجِّحَ الْمُجِلُّ لِلرَّسُولِ"],["وَشُهْرَةُ الْقِصَّةِ ذِكْرُ السَّبَبِ","وَسَمْعُهُ إِيَّاهُ دُونَ حُجُبِ"],["وَالْمَدَنِي وَالْخَبَرُ الَّذِي جَمَعْ","حُكْمًا وَعِلَّةً كَقَتْلِ مَنْ رَجَعْ"],["وَمَا بِهِ لِعِلَّةٍ تَقَدُّمُ","وَمَا بِتَوْكِيدٍ وَخَوْفٍ يُعْلَمُ"],["وَمَا يَعُمُّ مُطْلَقًا إِلَّا السَّبَبْ","فَقَدِّمَنْهُ تَقْضِ حُكْمًا قَدْ وَجَبْ"],["مَا مِنْهُ لِلشَّرْطِ عَلَى الْمُنَكَّرِ","وَهْوَ عَلَى كُلِّ الَّذِي لَهُ دُرِي"],["مُعَرَّفُ الْجَمْعِ عَلَى مَا اسْتُفْهِمَا","بِهِ مِنَ اللَّفْظَيْنِ أَعْنِي مَنْ وَمَا"],["وَذِي الثَّلَاثَةُ عَلَى الْمُعَرَّفِ","ذِي الْجِنْسِ لِاحْتِمَالِ عَهْدٍ قَدْ يَفِي"],["تَقْدِيمُ مَا خُصَّ عَلَى مَا لَمْ يُخَصّ","وَعَكْسُهُ كُلٌّ أَتَى عَلَيْهِ نَصّ"],["إِشَارَةٌ وَذَاتُ الْإِيمَا يُرْتَضَى","كَوْنُهُمَا مِنْ بَعْدِ ذَاتِ الِاقْتِضَا"],["هُمَا عَلَى الْمَفْهُومِ وَالْمُوَافَقَهْ","وَمَالِكٌ غَيْرُ الشُّذُوذِ وَافَقَهْ"],["وَنَاقِلٌ وَمُثْبِتٌ وَالْآمِرُ","بَعْدَ النَّوَاهِي ثُمَّ هَذَا الْآخِرُ"],["عَلَى الْإِبَاحَةِ وَهَكَذَا الْخَبَرْ","عَلَى النَّوَاهِي وَعَلَى الَّذِي أَمَرْ"],["فِي خَبَرَيْ إِبَاحَةٍ وَحَظْرِ","ثَالِثُهَا هَذَا كَذَاكَ يَجْرِي"],["وَالْجَزْمُ قَبْلَ النَّدْبِ وَالَّذِي نَفَى","حَدًّا عَلَى مَا الْحَدُّ فِيهِ أُلِفَا"],["مَا كَانَ مَدْلُولٌ لَهُ مَعْقُولَا","وَمَا عَلَى الْوَضْعِ أَتَى دَلِيلَا"],["رَجِّحْ عَلَى النَّصِّ الَّذِي قَدْ أُجْمِعَا","عَلَيْهِ وَالصَّحْبِي عَلَى مَنْ تَبِعَا"],["كَذَاكَ مَا انْقَرَضَ عَصْرُهُ وَمَا","فِيهِ الْعُمُومُ وَافَقُوا مَنْ عَلِمَا"],["بِقُوَّةِ الْمُثْبِتِ ذَا الْأَسَاسِ","أَيْ حُكْمَهُ التَّرْجِيحُ لِلْقِيَاسِ"],["وَكَوْنِهِ مُوَافِقَ السَّنَنِ عَنْ","بِالْقَطْعِ بِالْعِلَّةِ أَوْ غَالِبِ ظَنْ"],["وَقُوَّةِ الْمَسْلَكِ وَلْتُقَدِّمَا","مَا أَصْلُهَا تَتْرُكُهُ مُعَمَّمَا"],["وَذَاتَ الِانْعِكَاسِ وَاطِّرَادِ","فَذَاتَ الْآخِرِ بِلَا عِنَادِ"],["وَعِلَّةَ النَّصِّ وَمَا أَصْلَانِ","لَهَا كَمَا قَدْ مَرَّ يَجْرِيَانِ"],["فِي كَثْرَةِ الْفُرُوعِ خُلْفٌ قَدْ أَلَمْ","وَمَا تُقَلَّلَ تَطَرَّقَ الْعَدَمْ"],["ذَاتِيَّةً قَدِّمْ وَذَاتَ تَعْدِيَهْ","وَمَا احْتِيَاطًا عُلِمَتْ مُقْتَضِيَهْ"],["وَقَدِّمَنْ مَا حُكْمُ أَصْلِهَا جَرَى","مُعَلَّلًا وَفْقًا لَدَى مَنْ غَبَرَا"],["بَعْدَ الْحَقِيقِيِّ أَتَى الْعُرْفِيُّ","وَبَعْدَ هَذَيْنِ أَتَى الشَّرْعِيُّ"],["وَفِي الْحُدُودِ الْأَشْهَرُ الْمُقَدَّمُ","وَمَا صَرِيحًا أَوْ أَعَمَّ يُعْلَمُ"],["وَمَا يُوَافِقُ لِنَقْلٍ مُطْلَقَا","وَالْحَدُّ سَائِرَ الرُّسُومِ سَبَقَا"],["وَقَدْ خَلَتْ مُرَجِّحَاتٌ فَاعْتَبِرْ","وَاعْلَمْ بِأَنَّ كُلَّهَا لَا يَنْحَصِرْ"],["قُطْبُ رَحَاهَا قُوَّةُ الْمَظِنَّهْ","فَهْيَ لَدَى تَعَارُضٍ مَئِنَّهْ"],["بَذْلُ الْفَقِيهِ الْوُسْعَ أَنْ يُحَصِّلَا","ظَنًّا بِأَنَّ ذَاكَ حَتْمٌ مَثَلَا"],["وَذَاكَ مَعْ مُجْتَهِدٍ رَدِيفُ","وَمَا لَهُ يُحَقِّقُ التَّكْلِيفُ"],["وَهْوَ شَدِيدُ الْفَهْمِ طَبْعًا وَاخْتُلِفْ","فِيمَنْ بِإِنْكَارِ الْقِيَاسِ قَدْ عُرِفْ"],["قَدْ عَرَفَ التَّكْلِيفَ بِالدَّلِيلِ","ذِي الْعَقْلِ قَبْلَ صَارِفِ النُّقُولِ"],["وَالنَّحْوَ وَالْمِيزَانَ وَاللُّغَةَ مَعْ","عِلْمِ الْأُصُولِ وَبَلَاغَةً جَمَعْ"],["وَمَوْضِعَ الْأَحْكَامِ دُونَ شَرْطِ","حِفْظِ الْمُتُونِ عِنْدَ أَهْلِ الضَّبْطِ"],["ذُو رُتْبَةٍ وُسْطَى فِي كُلِّ مَا غَبَرْ","وَعِلْمُ الِاجْمَاعَاتِ مِمَّا يُعْتَبَرْ"],["كَشَرْطِ الْآحَادِ وَمَا تَوَاتَرَا","وَمَا صَحِيحًا أَوْ ضَعِيفًا قَدْ جَرَى"],["وَمَا عَلَيْهِ أَوْ بِهِ النَّسْخُ وَقَعْ","وَسَبَبُ النُّزُولِ شَرْطٌ مُتَّبَعْ"],["كَحَالَةِ الرُّوَاةِ وَالْأَصْحَابِ","وَقَلِّدَنْ فِي ذَا عَلَى الصَّوَابِ"],["وَلَيْسَ الِاجْتِهَادُ مِمَّنْ قَدْ جَهِلْ","عِلْمَ الْفُرُوعِ وَالْكَلَامِ يَنْحَظِلْ"],["كَالْعَبْدِ وَالْأُنْثَى كَذَا لَا يَجِبُ","عَدَالَةٌ عَلَى الَّذِي يُنْتَخَبُ"],["هَذَا هُوَ الْمُطْلَقُ وَالْمُقَيَّدُ","مُنْسَفِلَ الرُّتْبَةِ عَنْهُ يُوجَدُ"],["مُلْتَزِمٌ أُصُولَ ذَاكَ الْمُطْلَقِ","فَلَيْسَ يَعْدُوهَا عَلَى الْمُحَقَّقِ"],["مُجْتَهِدُ الْمَذْهَبِ مَنْ أُصُولُهُ","مَنْصُوصَةً أَوْ لَا حَوَى مَعْقُولُهُ"],["وَشَرْطُهُ التَّخْرِيجُ لِلْأَحْكَامِ","عَلَى نُصُوصِ ذَلِكَ الْإِمَامِ"],["مُجْتَهِدُ الْفُتْيَا الَّذِي يُرَجِّحُ","قَوْلًا عَلَى قَوْلٍ وَذَاكَ أَرْجَحُ"],["لِجَاهِلِ الْأُصُولِ أَنْ يُفْتِي بِمَا","نَقَلَ مُسْتَوْفًى فَقَطْ وَأَمِّمَا"],["يَجُوزُ الِاجْتِهَادُ فِي فَنٍّ فَقَطْ","أَوْ فِي قَضِيَّةٍ وَبَعْضٌ قَدْ رَبَطْ"],["وَالْخُلْفَ فِي جَوَازِ الِاجْتِهَادِ أَوْ","وُقُوعِهِ مِنَ النَّبِيِّ قَدْ رَوَوْا"],["وَوَاجِبُ الْعِصْمَةِ يَمْنَعُ الْجَنَفْ","وَصَحَّحَ الْوُقُوعَ عَصْرَهُ السَّلَفْ"],["وَوَحِّدِ الْمُصِيبَ فِي الْعَقْلِيِّ","وَمَالِكٌ رَآهُ فِي الْفَرْعِيِّ"],["فَالْحُكْمُ فِي مَذْهَبِهِ مُعَيَّنُ","لَهُ عَلَى الصَّحِيحِ مَا يُبَيِّنُ"],["مُخْطِئُهُ وَإِنْ عَلَيْهِ انْحَتَمَا","إِصَابَةٌ لَهُ الثَّوَابُ ارْتَسَمَا"],["وَمَنْ رَأَى كُلًّا مُصِيبًا يَعْتَقِدْ","لِأَنَّهُ يَتْبَعُ ظَنَّ الْمُجْتَهِدْ"],["أَوْ ثَمَّ مَا لَوْ عُيِّنَ الْحُكْمُ حَكَمْ","بِهِ لِدَرْءٍ أَوْ لِجَلْبٍ قَدْ أَلَمْ"],["لِذَا يُصَوِّبُونَ فِي ابْتِدَاءِ","وَالِاجْتِهَادِ دُونَ الِانْتِهَاءِ"],["وَالْحُكْمِ وَهْوَ وَاحِدٌ مَتَى عُقِلْ","فِي الْفَرْعِ قَاطِعٌ وَلَكِنْ قَدْ جُهِلْ"],["وَهُوَ آثِمٌ مَتَى مَا قَصَّرَا","فِي نَظَرٍ وَفْقًا لَدَى مَنْ قَدْ دَرَى"],["وَالْحُكْمُ مِنْ مُجْتَهِدٍ كَيْفَ وَقَعْ","دُونَ شُذُوذٍ نَقْضُهُ قَدِ امْتَنَعْ"],["إِلَّا إِذَا النَّصَّ أَوِ الْإِجْمَاعَ أَوْ","قَاعِدَةً خَالَفَ فِيمَا قَدْ رَأَوْا"],["أَوِ اجْتِهَادَهُ أَوِ الْقَيْسَ الْجَلِي","عَلَى الْأَصَحِّ أَوْ بِغَيْرِ الْمُعْتَلِي"],["حَكَمَ فِي مَذْهَبِهِ وَإِنْ وَصَلْ","لِرُتْبَةِ التَّرْجِيحِ فَالنَّقْضُ انْحَظَلْ"],["وَقَدِّمِ الضَّعِيفَ إِنْ جَرَى عَمَلْ","بِهِ لِأَجْلِ سَبَبٍ قَدِ اتَّصَلْ"],["وَهَلْ يَقِيسُ ذُو الْأُصُولِ إِنْ عُدِمْ","نَصُّ إِمَامِهِ الَّذِي لَهُ لَزِمْ"],["مَعَ الْتِزَامِ مَا لَهُ أَوْ مُطْلَقَا","وَبَعْضُهُمْ بِنَصِّهِ تَعَلَّقَا"],["وَلَمْ يُضَمَّنْ ذُو اجْتِهَادٍ ضَيَّعَا","إِنْ يَكُ لَا لِقَاطِعٍ قَدْ رَجَعَا"],["إِلَّا فَهَلْ يَضْمَنُ أَوْ لَا يَضْمَنُ","إِنْ لَمْ يَكُنْ مِنْهُ تَوَلٍّ بَيِّنُ"],["وَإِنْ يَكُنْ مُنْتَصِبًا فَالنَّظَرُ","ذَاكَ وِفَاقًا عِنْدَ مَنْ يُحَرِّرُ"],["هُوَ الْتِزَامُ مَذْهَبِ الْغَيْرِ بِلَا","عِلْمِ دَلِيلِهِ الَّذِي تَأَصَّلَا"],["يَلْزَمُ غَيْرَ ذِي اجْتِهَادٍ مُطْلَقِ","وَإِنْ مُقَيَّدًا إِذَا لَمْ يُطِقِ"],["وَهُوَ لِلْمُجْتَهِدِينَ مُمْتَنِعْ","لِنَظَرٍ قَدْ رُزِقُوهُ مُتَّسِعْ"],["وَلَيْسَ فِي فَتْوَاهُ مُفْتٍ يُتَّبَعْ","إِنْ لَمْ يُضِفْ لِلدِّينِ وَالْعِلْمِ الْوَرَعْ"],["مَنْ لَمْ يَكُنْ بِالْعِلْمِ وَالْعَدْلِ اشْتَهَرْ","أَوْ حَصَلَ الْقَطْعُ فَالِاسْتِفْتَا انْحَظَرْ"],["وَوَاجِبٌ تَجْدِيدُ ذِي الرَّأْيِ النَّظَرْ","إِذَا مُمَاثِلٌ عَرَا وَمَا ذَكَرْ"],["لِلنَّصِّ مِثْلُ مَا إِذَا تَجَدَّدَا","مُغَيَّرٌ إِلَّا فَلَنْ يُجَدِّدَا"],["وَهَلْ يُكَرِّرُ سُؤَالَ الْمُجْتَهِدْ","مَنْ عَمَّ إِنْ مُمَاثِلُ الْفَتْوَى يَعُدْ"],["وَثَانِيًا ذَا النَّقْلِ صِرْفًا أَهْمِلِ","وَخَيِّرَنْ لَدَى اسْتِوَاءِ السُّبُلِ"],["وَزَائِدًا فِي الْعِلْمِ بَعْضٌ قَدَّمَا","وَقَدَّمَ الْأَوْرَعَ كُلُّ الْقُدَمَا"],["وَجَائِزٌ تَقْلِيدُ ذِي اجْتِهَادِ","وَهُوَ مَفْضُولٌ بِلَا اسْتِبْعَادِ"],["فَكُلُّ مَذْهَبٍ وَسِيلَةً إِلَى","دَارِ الْحُبُورِ وَالْقُصُورِ جُعِلَا"],["وَمُوجِبٌ تَقْلِيدَ الْأَرْجَحِ وَجَبْ","لَدَيْهِ بَحْثٌ عَنْ إِمَامٍ مُنْتَخَبْ"],["إِذَا سَمِعْتَ فَالْإِمَامُ مَالِكُ","صَحَّ لَهُ الشَّأْوُ الَّذِي لَا يُدْرَكُ"],["لِلْأَثَرِ الصَّحِيحِ مَعْ حُسْنِ النَّظَرْ","فِي كُلِّ فَنٍّ كَالْكِتَابِ وَالْأَثَرْ"],["وَالْخُلْفُ فِي تَقْلِيدِ مَنْ مَاتَ وَفِي","بَيْعِ طُرُوسِ الْفِقْهِ الْآنَ قَدْ نُفِي"],["وَلَكَ أَنْ تَسْأَلَ لِلتَّثَبُّتِ","عَنْ مَأْخَذِ الْمَسْؤُولِ لَا التَّعَنُّتِ"],["ثُمَّ عَلَيْهِ غَايَةُ الْبَيَانِ","إِنْ لَمْ يَكُنْ عُذْرٌ بِالِاكْتِنَانِ"],["يُنْدَبُ لِلْمُفْتِي اطِّرَاحُهُ النَّظَرْ","إِلَى الْحُطَامِ جَاعِلَ الرِّضَا الْوَطَرْ"],["مُتَّصِفًا بِحِلْيَةِ الْوَقَارِ","مُحَاشِيًا مَجَالِسَ الْأَشْرَارِ"],["وَالْأَرْضُ لَا عَنْ قَائِمٍ مُجْتَهِدِ","تَخْلُو إِلَى تَزَلْزُلِ الْقَوَاعِدِ"],["وَهُوَ جَائِزٌ بِحُكْمِ الْعَقْلِ","مَعَ احْتِمَالِ كَوْنِهِ بِالنَّقْلِ"],["وَإِنْ بِقَوْلِ ذِي اجْتِهَادٍ قَدْ عَمِلْ","مَنْ عَمَّ فَالرُّجُوعُ عَنْهُ مُنْحَظِلْ"],["إِلَّا فَهَلْ يَلْزَمُ أَوْ لَا يَلْزَمُ","إِلَّا الَّذِي شَرَعَ أَوْ يَلْتَزِمُ"],["رُجُوعُهُ لِغَيْرِهِ فِي آخَرِ","يَجُوزُ لِلْإِجْمَاعِ عِنْدَ الْأَكْثَرِ"],["وَذُو الْتِزَامِ مَذْهَبٍ هَلْ يَنْتَقِلْ","أَوْ لَا وَتَفْصِيلٌ أَصَحُّ مَا نُقِلْ"],["وَمَنْ أَجَازَ لِلْخُرُوجِ قَيَّدَا","بِأَنَّهُ لَابُدَّ أَنْ يَعْتَقِدَا"],["فَضْلًا لَهُ وَأَنَّهُ لَمْ يَبْتَدِعْ","بِخُلْفِ الِاجْمَاعِ وَإِلَّا يَمْتَنِعْ"],["وَعَدَمِ التَّقْلِيدِ فِيمَا لَوْ حَكَمْ","قَاضٍ بِهِ بِالنَّقْضِ حُكْمُهُ يُؤَمّ"],["أَمَّا التَّمَذْهُبُ بِغَيْرِ الْأَوَّلِ","فَصُنْعُ غَيْرِ وَاحِدٍ مُبَجَّلِ"],["كَحُجَّةِ الْإِسْلَامِ وَالطَّحَاوِي","وَابْنِ دَقِيقِ الْعِيدِ ذِي الْفَتَاوِي"],["أَنْ يَنْتَقِلْ لِغَرَضٍ صَحِيحِ","كَكَوْنِهِ سَهْلًا أَوِ التَّرْجِيحِ"],["وَذُمَّ مَنْ نَوَى الدُّنَا بِالْقَيْسِ","عَلَى مُهَاجِرٍ لِأُمِّ قَيْسِ"],["وَإِنْ عَنِ الْقَصْدَيْنِ قَدْ تَجَرَّدَا","مَنْ عَمَّ فَلْتُبِحْ لَهُ مَا قَصَدَا"],["ثُمَّ الْتِزَامُ مَذْهَبٍ قَدْ ذُكِرَا","صِحَّةُ فَرْضِهِ عَلَى مَنْ قَصُرَا"],["وَالْمُجْمَعُ الْيَوْمَ عَلَيْهِ الْأَرْبَعَهْ","وَقَفْوُ غَيْرِهَا الْجَمِيعُ مَنَعَهْ"],["حَتَّى يَجِيءَ الْفَاطِمِي الْمُجَدِّدُ","دِينَ الْهُدَى لِأَنَّهُ مُجْتَهِدُ"],["أَنْهَيْتُ مَا جَمَّعَهُ اجْتِهَادِي","وَضَرْبِيَ الْأَغْوَارَ مَعَ الْأَنْجَادِ"],["مِمَّا أَفَادَنِيهِ دَرْسُ الْبَرَرَهْ","مِمَّا انْطَوَتْ عَلَيْهِ كُتْبُ الْمَهَرَهْ"],["كَالشَّرْحِ لِلتَّنْقِيحِ وَالتَّنْقِيحِ","وَالْجَمْعِ وَالْآيَاتِ وَالتَّلْوِيحِ"],["مُطَالِعًا لِابْنِ حُلُولُو اللَّامِعَا","مَعَ حَوَاشٍ تُعْجِبُ الْمُطَالِعَا"],["فَالْحَمْدُ لِلَّهِ الْعَلِيِّ الْمُجْزِلِ","الْمَانِحِ الْفَضْلَ لَنَا الْمُكَمِّلِ"],["لِنِعَمٍ عَنْهَا يَكِلُّ الْعَدُّ","لَوْ كَانَ مَا فِي الْأَرْضِ لِي يَمُدُّ"],["ثُمَّ صَلَاةُ اللَّهِ وَالسَّلَامُ","عَلَى الَّذِي انْجَلَى بِهِ الظَّلَامُ"],["مُحَمَّدِ الَّذِي سَمَا فَوْقَ السَّمَا","وَأَهْلِهِ مِنْ بَعْدِ مَا الْأَرْضَ سَمَا"],["أَسْأَلُهُ الْحُسْنَى وَزَيْدًا وَالرِّضَا","وَاللُّطْفَ بِي فِي كُلِّ أَمْرٍ قَدْ قَضَى"]],"secs":{"13":"مُقَدِّمَةٌ","16":"أُصُولُ الْفِقْهِ","18":"فَصْلٌ","124":"كِتَابُ الْقُرْآنِ وَمَبَاحِثِ الْأَلْفَاظِ","134":"الْمَنْطُوقُ وَالْمَفْهُومُ","161":"فَصْلٌ","173":"فَصْلٌ فِي الِاشْتِقَاقِ","187":"فَصْلٌ فِي التَّرَادُفِ","194":"الْمُشْتَرَكُ","199":"فَصْلٌ فِي الْحَقِيقَةِ","203":"الْمَجَازُ","224":"الْمُعَرَّبُ","228":"الْكِنَايَةُ وَالتَّعْرِيضُ","236":"الْأَمْرُ","318":"الْوَاجِبُ الْمُوَسَّعُ","323":"الْوَاجِبُ الْمُخَيَّرُ","324":"ذُو الْكِفَايَةِ","340":"النَّهْيُ","350":"الْعَامُّ","379":"مَا عَدَمُ الْعُمُومِ فِيهِ أَرْجَحُ","382":"التَّخْصِيصُ","394":"الْمُخَصِّصُ الْمُتَّصِلُ","423":"الْمُخَصِّصُ الْمُنْفَصِلُ","432":"الْمُقَيَّدُ وَالْمُطْلَقُ","441":"التَّأْوِيلُ وَالْمُحْكَمُ وَالْمُجْمَلُ","454":"الْبَيَانُ","466":"النَّسْخُ","490":"كِتَابُ السُّنَّةِ","592":"كَيْفِيَّةُ رِوَايَةِ الصَّحَابِيِّ","596":"كَيْفِيَّةُ رِوَايَةِ غَيْرِهِ عَنْ شَيْخِهِ","603":"كِتَابُ الْإِجْمَاعِ","631":"كِتَابُ الْقِيَاسِ","639":"أَرْكَانُهُ","643":"الرُّكْنُ الثَّانِي وَهْوَ الْحُكْمُ","653":"الْفَرْعُ","661":"الْعِلَّةُ","681":"مَسَالِكُ الْعِلَّةِ","762":"الْقَوَادِحُ","810":"خَاتِمَةٌ","819":"كِتَابُ الِاسْتِدْلَالِ","851":"كِتَابُ التَّعَادُلِ وَالتَّرَاجِيحِ","873":"التَّرْجِيحُ بِاعْتِبَارِ حَالِ الرَّاوِي","884":"التَّرْجِيحُ بِاعْتِبَارِ حَالِ الْمَرْوِيِّ","897":"التَّرْجِيحُ بِاعْتِبَارِ حَالِ الْمَدْلُولِ","902":"تَرْجِيحُ الْإِجْمَاعَاتِ","904":"تَرْجِيحُ الْأَقْيِسَةِ وَالْحُدُودِ","917":"كِتَابُ الِاجْتِهَادِ فِي الْفُرُوعِ","956":"فَصْلٌ فِي التَّقْلِيدِ فِي الْفُرُوعِ","993":"خَاتِمَةٌ"}}],"sharh":false};
